"}, {"type": "CODE_BLOCK", "language": "java", "content": "// AllowedFileExtension.java
package com.example.filedownload;

import java.util.Arrays;
import java.util.Locale;
import java.util.Optional;

/**
 * Whitelist der erlaubten Dateiendungen inklusive des jeweils erwarteten
 * MIME-Types. Nur Dateien, deren Endung UND tatsächlicher Inhalt zu einem
 * dieser Einträge passen, dürfen ausgeliefert werden (Schutz vor CWE-434).
 */
public enum AllowedFileExtension {

    TXT("txt", "text/plain"),
    PDF("pdf", "application/pdf"),
    PNG("png", "image/png"),
    JPG("jpg", "image/jpeg"),
    JPEG("jpeg", "image/jpeg"),
    GIF("gif", "image/gif");

    private final String extension;
    private final String expectedMimeType;

    AllowedFileExtension(String extension, String expectedMimeType) {
        this.extension = extension;
        this.expectedMimeType = expectedMimeType;
    }

    public String getExtension() {
        return extension;
    }

    public String getExpectedMimeType() {
        return expectedMimeType;
    }

    public static Optional<AllowedFileExtension> fromExtension(String extension) {
        if (extension == null) {
            return Optional.empty();
        }
        String normalized = extension.toLowerCase(Locale.ROOT);
        return Arrays.stream(values())
                .filter(value -> value.extension.equals(normalized))
                .findFirst();
    }
}
