"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureFileStorageService.java
package com.example.filedownload;

import org.apache.commons.io.FilenameUtils;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.regex.Pattern;

/**
 * Zentrale Sicherheitsschicht für den Zugriff auf Dateien im Upload-Verzeichnis.
 *
 * Umsetzung von CERT IDS02-J / CWE-22 / CWE-23 / CWE-36 / CWE-171:
 * Der Benutzereingabe wird zunächst mit FilenameUtils.getName(...) jeglicher
 * Pfadanteil entzogen, das Ergebnis wird gegen eine strikte Whitelist geprüft
 * und erst danach mit dem kanonisierten Basisverzeichnis kombiniert und
 * erneut kanonisiert. Die Validierung erfolgt ausschließlich auf Basis des
 * kanonischen Pfades.
 */
@Service
public class SecureFileStorageService {

    private static final long MAX_FILE_SIZE_BYTES = 10L * 1024 * 1024; // 10 MB

    // Nur alphanumerische Zeichen, '_' und '-' im Namen, genau ein Punkt vor der Endung.
    // Schließt Pfadtrenner, Nullbytes und ".."-Sequenzen bereits syntaktisch aus.
    private static final Pattern SAFE_FILENAME_PATTERN =
            Pattern.compile("^[A-Za-z0-9_-]{1,100}\\.[A-Za-z0-9]{1,10}$");

    private final Path secureBaseDirectory;

    public SecureFileStorageService(@Value("${app.upload.dir:uploads}") String uploadDir) {
        try {
            File configuredDirectory = new File(uploadDir);
            this.secureBaseDirectory = configuredDirectory.getCanonicalFile().toPath().normalize();
        } catch (IOException e) {
            throw new IllegalStateException("Konfiguriertes Upload-Verzeichnis konnte nicht kanonisiert werden", e);
        }
        if (!Files.isDirectory(secureBaseDirectory)) {
            throw new IllegalStateException("Konfiguriertes Upload-Verzeichnis ist kein gültiges Verzeichnis: "
                    + secureBaseDirectory);
        }
    }

    /**
     * Lädt eine Datei aus dem Upload-Verzeichnis, nachdem Name, Pfad,
     * Erweiterung und tatsächlicher Content-Type validiert wurden.
     */
    public FileDownloadResult loadFileContent(String rawFileName) {
        // 1. Nur den reinen Dateinamen aus der Benutzereingabe extrahieren,
        //    um jegliche Pfadanteile (auch verschleierte) zu entfernen.
        String safeFileName = validateAndSanitizeFileName(rawFileName);

        // 2. Kandidatenpfad ausschließlich aus dem validierten, reinen
        //    Dateinamen und dem festen Basisverzeichnis bilden.
        File candidateFile = new File(secureBaseDirectory.toFile(), safeFileName);

        File canonicalFile;
        Path canonicalPath;
        try {
            canonicalFile = candidateFile.getCanonicalFile();
            canonicalPath = canonicalFile.toPath();
        } catch (IOException e) {
            throw new FileNotAccessibleException("Angeforderte Datei konnte nicht aufgelöst werden", e);
        }

        // 3. IDS02-J: Validierung erfolgt ausschließlich auf Basis des kanonischen Pfades.
        //    startsWith auf Path-Ebene vermeidet String-Präfix-Fallstricke
        //    (z. B. "/upload-evil" vs. "/upload").
        if (!canonicalPath.startsWith(secureBaseDirectory) || canonicalPath.equals(secureBaseDirectory)) {
            throw new InvalidFileRequestException("Angeforderte Datei liegt außerhalb des erlaubten Verzeichnisses");
        }

        // 4. Zusätzliche Absicherung: direkter Kindpfad ohne weitere Unterverzeichnisse.
        Path relative = secureBaseDirectory.relativize(canonicalPath);
        if (relative.getNameCount() != 1) {
            throw new InvalidFileRequestException("Angeforderte Datei liegt außerhalb des erlaubten Verzeichnisses");
        }

        // 5. Der finale Dateiname muss exakt dem validierten Namen entsprechen
        //    (verhindert z. B. Symlink-Umbenennungen oder Groß-/Kleinschreibungs-Tricks).
        if (!canonicalFile.getName().equals(safeFileName)) {
            throw new InvalidFileRequestException("Angeforderte Datei entspricht nicht dem erwarteten Namen");
        }

        if (!canonicalFile.isFile() || !canonicalFile.canRead()) {
            throw new FileNotAccessibleException("Angeforderte Datei existiert nicht oder ist nicht lesbar");
        }

        if (canonicalFile.length() > MAX_FILE_SIZE_BYTES) {
            throw new InvalidFileRequestException("Angeforderte Datei überschreitet die maximal erlaubte Größe");
        }

        String extension = extractExtension(canonicalFile.getName());
        AllowedFileExtension allowedExtension = AllowedFileExtension.fromExtension(extension)
                .orElseThrow(() -> new InvalidFileRequestException("Dateierweiterung ist nicht zulässig"));

        String actualContentType;
        try {
            actualContentType = Files.probeContentType(canonicalPath);
        } catch (IOException e) {
            throw new FileNotAccessibleException("Content-Type der Datei konnte nicht ermittelt werden", e);
        }

        if (actualContentType == null
                || !actualContentType.equalsIgnoreCase(allowedExtension.getExpectedMimeType())) {
            throw new InvalidFileRequestException(
                    "Tatsächlicher Content-Type der Datei entspricht nicht der erwarteten Erweiterung");
        }

        byte[] content;
        try (FileInputStream inputStream = new FileInputStream(canonicalFile)) {
            content = inputStream.readAllBytes();
        } catch (IOException e) {
            throw new FileNotAccessibleException("Fehler beim Lesen des Dateiinhalts", e);
        }

        return new FileDownloadResult(content, actualContentType, canonicalFile.getName());
    }

    /**
     * Validiert die Benutzereingabe strikt und extrahiert ausschließlich den
     * reinen Dateinamen (kein Pfadanteil, keine "..", keine Separatoren).
     */
    private String validateAndSanitizeFileName(String rawFileName) {
        if (rawFileName == null || rawFileName.isBlank()) {
            throw new InvalidFileRequestException("Dateiname darf nicht leer sein");
        }

        // Nullbytes explizit verbieten (können Pfadprüfungen umgehen).
        if (rawFileName.indexOf('\0') >= 0) {
            throw new InvalidFileRequestException("Dateiname enthält unzulässige Zeichen");
        }

        // Nur den reinen Dateinamen betrachten, unabhängig davon, ob der
        // Client Pfadanteile mitschickt (Defense in Depth). FilenameUtils.getName
        // entfernt zuverlässig sowohl Unix- als auch Windows-Pfadanteile.
        String baseName = FilenameUtils.getName(rawFileName);

        if (baseName == null || baseName.isBlank() || !baseName.equals(rawFileName)) {
            throw new InvalidFileRequestException("Dateiname darf keine Pfadanteile enthalten");
        }

        if (baseName.contains("..")
                || baseName.contains("/")
                || baseName.contains("\\")
                || baseName.contains(":")) {
            throw new InvalidFileRequestException("Dateiname enthält unzulässige Zeichen");
        }

        if (!SAFE_FILENAME_PATTERN.matcher(baseName).matches()) {
            throw new InvalidFileRequestException("Dateiname hat ein ungültiges Format");
        }

        return baseName;
    }

    private String extractExtension(String fileName) {
        int lastDot = fileName.lastIndexOf('.');
        if (lastDot < 0 || lastDot == fileName.length() - 1) {
            throw new InvalidFileRequestException("Datei besitzt keine erkennbare Erweiterung");
        }
        return fileName.substring(lastDot + 1);
    }
}
