"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FileDownloadController.java
package com.example.filedownload;

import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.nio.charset.StandardCharsets;

/**
 * REST-Endpoint zum Herunterladen von Dateien aus dem Upload-Verzeichnis.
 * Enthält bewusst KEINE Sicherheitslogik – diese liegt vollständig in
 * SecureFileStorageService, um Wiederverwendbarkeit und Testbarkeit
 * zu gewährleisten und Prüfungen nicht versehentlich zu vergessen.
 */
@RestController
@RequestMapping("/api/files")
public class FileDownloadController {

    private final SecureFileStorageService fileStorageService;

    public FileDownloadController(SecureFileStorageService fileStorageService) {
        this.fileStorageService = fileStorageService;
    }

    @GetMapping("/download")
    public ResponseEntity<byte[]> downloadFile(@RequestParam("fileName") String fileName) {
        FileDownloadResult result = fileStorageService.loadFileContent(fileName);

        ContentDisposition disposition = ContentDisposition.attachment()
                .filename(result.getFileName(), StandardCharsets.UTF_8)
                .build();

        return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType(result.getContentType()))
                .header(HttpHeaders.CONTENT_DISPOSITION, disposition.toString())
                .body(result.getData());
    }
}
