"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FileApiExceptionHandler.java
package com.example.filedownload;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Zentrale Fehlerbehandlung für die File-Download-API.
 *
 * Interne Details (Stacktraces, Pfade, technische Ursachen) werden
 * ausschließlich serverseitig geloggt und niemals an den Client
 * zurückgegeben, um Information Disclosure (CWE-209) zu vermeiden.
 */
@RestControllerAdvice
public class FileApiExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(FileApiExceptionHandler.class);

    @ExceptionHandler(InvalidFileRequestException.class)
    public ResponseEntity<String> handleInvalidRequest(InvalidFileRequestException ex) {
        log.warn("Ungültige Dateianfrage abgelehnt: {}", ex.getMessage());
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body("Ungültige Dateianfrage.");
    }

    @ExceptionHandler(FileNotAccessibleException.class)
    public ResponseEntity<String> handleNotAccessible(FileNotAccessibleException ex) {
        log.warn("Datei konnte nicht zugegriffen werden: {}", ex.getMessage(), ex);
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body("Angeforderte Datei nicht gefunden.");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<String> handleGeneric(Exception ex) {
        log.error("Unerwarteter Fehler bei der Dateiverarbeitung", ex);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("Ein unerwarteter Fehler ist aufgetreten.");
    }
}
