package com.example.filedownload.exception;

/**
 * Wird geworfen, wenn ein Zugriff auf eine Datei aufgrund
 * fehlgeschlagener Sicherheitsprüfungen (z.B. Path Traversal) verweigert wird.
 *
 * Die Exception gibt bewusst KEINE internen Pfadinformationen preis,
 * um CWE-200 (Exposure of Sensitive Information) zu vermeiden.
 */
public class FileAccessDeniedException extends RuntimeException {

    public FileAccessDeniedException(String message) {
        super(message);
    }

    public FileAccessDeniedException(String message, Throwable cause) {
        super(message, cause);
    }
}
