package com.example.filedownload.config;

import jakarta.validation.constraints.NotBlank;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.validation.annotation.Validated;

/**
 * Konfigurierbares Basisverzeichnis für Datei-Downloads.
 * Wird typischerweise über application.yml gesetzt:
 *
 * app:
 *   file-storage:
 *     base-directory: data/docs
 *
 * Durch die Auslagerung in eine Property-Klasse ist das
 * Basisverzeichnis nicht hartkodiert und kann pro Umgebung
 * (Dev/Test/Prod) unterschiedlich konfiguriert werden.
 */
@Validated
@ConfigurationProperties(prefix = "app.file-storage")
public class FileStorageProperties {

    @NotBlank
    private String baseDirectory = "data/docs";

    public String getBaseDirectory() {
        return baseDirectory;
    }

    public void setBaseDirectory(String baseDirectory) {
        this.baseDirectory = baseDirectory;
    }
}
