package com.example.filedownload.service;

import com.example.filedownload.config.FileStorageProperties;
import com.example.filedownload.exception.FileAccessDeniedException;
import com.example.filedownload.exception.FileNotFoundServiceException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.Resource;
import org.springframework.core.io.UrlResource;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.MalformedURLException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.regex.Pattern;

/**
 * Zentrale, wiederverwendbare Sicherheitskomponente für Dateizugriffe.
 *
 * Verhindert CWE-22 (Path Traversal) durch:
 *  1. Whitelist-Validierung des Dateinamens per Regex (keine Sonderzeichen,
 *     kein "..", kein Pfadtrenner).
 *  2. Normalisierung + Canonicalization des aufgelösten Pfads.
 *  3. Verifikation, dass der aufgelöste, reale Pfad tatsächlich
 *     innerhalb des konfigurierten Basisverzeichnisses liegt
 *     (Prüfung erfolgt NACH Auflösung von Symlinks/".." via toRealPath(),
 *     damit CWE-59/61 Symlink-Angriffe ebenfalls abgefangen werden).
 */
@Service
public class FileStorageService {

    private static final Logger log = LoggerFactory.getLogger(FileStorageService.class);

    // Erlaubt nur: Buchstaben, Zahlen, Punkt, Bindestrich, Unterstrich.
    // Kein "/", "\", ".." oder Nullbyte möglich.
    private static final Pattern SAFE_FILENAME_PATTERN =
            Pattern.compile("^[A-Za-z0-9](?:[A-Za-z0-9._-]{0,250})?$");

    private final Path baseDirectory;

    public FileStorageService(FileStorageProperties properties) {
        try {
            // Basisverzeichnis wird beim Start einmalig real aufgelöst.
            this.baseDirectory = Paths.get(properties.getBaseDirectory())
                    .toAbsolutePath()
                    .normalize();

            Files.createDirectories(this.baseDirectory);
        } catch (IOException e) {
            throw new IllegalStateException(
                    "Basisverzeichnis für Dateizugriffe konnte nicht initialisiert werden.", e);
        }
    }

    /**
     * Lädt eine Datei als Resource, nachdem der übergebene Dateiname
     * streng gegen Path-Traversal validiert wurde.
     *
     * @param requestedFileName vom Client übermittelter Dateiname (nicht Pfad!)
     * @return validierte, existierende und lesbare Resource
     * @throws FileAccessDeniedException     bei ungültigem Namen oder Traversal-Versuch
     * @throws FileNotFoundServiceException  wenn Datei nicht existiert/lesbar ist
     */
    public Resource loadFileAsResource(String requestedFileName) {

        validateFileNameSyntax(requestedFileName);

        // Auflösung relativ zum Basisverzeichnis. normalize() entfernt
        // "." und ".." Segmente rein syntaktisch – die eigentliche
        // Sicherheitsprüfung folgt danach über den REALEN Pfad.
        Path resolvedPath = baseDirectory.resolve(requestedFileName).normalize();

        // Sicherheitsprüfung 1: Liegt der normalisierte Pfad überhaupt
        // (rein syntaktisch) noch innerhalb des Basisverzeichnisses?
        if (!resolvedPath.startsWith(baseDirectory)) {
            log.warn("Path traversal attempt detected for requested file (rejected before existence check).");
            throw new FileAccessDeniedException("Zugriff auf die angeforderte Datei ist nicht erlaubt.");
        }

        if (!Files.exists(resolvedPath) || !Files.isRegularFile(resolvedPath)) {
            throw new FileNotFoundServiceException("Die angeforderte Datei wurde nicht gefunden.");
        }

        try {
            // Sicherheitsprüfung 2: Auflösung von Symlinks etc.
            // Verhindert, dass ein Symlink innerhalb von baseDirectory
            // auf eine Datei außerhalb zeigt (CWE-59/61).
            Path realPath = resolvedPath.toRealPath();
            if (!realPath.startsWith(baseDirectory.toRealPath())) {
                log.warn("Symlink escape attempt detected for requested file (rejected after realpath check).");
                throw new FileAccessDeniedException("Zugriff auf die angeforderte Datei ist nicht erlaubt.");
            }

            if (!Files.isReadable(realPath)) {
                throw new FileNotFoundServiceException("Die angeforderte Datei ist nicht lesbar.");
            }

            Resource resource = new UrlResource(realPath.toUri());
            if (!resource.exists() || !resource.isReadable()) {
                throw new FileNotFoundServiceException("Die angeforderte Datei ist nicht verfügbar.");
            }
            return resource;

        } catch (MalformedURLException e) {
            throw new FileNotFoundServiceException("Die angeforderte Datei konnte nicht geladen werden.", e);
        } catch (IOException e) {
            throw new FileAccessDeniedException("Zugriff auf die angeforderte Datei ist nicht erlaubt.", e);
        }
    }

    /**
     * Validiert die Syntax des Dateinamens gegen eine strenge Whitelist.
     * Lehnt u.a. ab: leere Strings, führende Punkte/Bindestriche,
     * Pfadtrenner, ".." Sequenzen, Nullbytes, überlange Namen.
     */
    private void validateFileNameSyntax(String fileName) {
        if (fileName == null || fileName.isBlank()) {
            throw new FileAccessDeniedException("Dateiname darf nicht leer sein.");
        }

        // Explizite Ablehnung von Nullbytes (CWE-158 verwandte Angriffe)
        if (fileName.indexOf('\0') >= 0) {
            throw new FileAccessDeniedException("Ungültiger Dateiname.");
        }

        // Explizite Ablehnung von Pfadtrennern und Traversal-Sequenzen,
        // auch wenn die Regex das bereits implizit verhindert –
        // Defense in Depth / Fail-Fast mit klarer Fehlermeldung.
        if (fileName.contains("..") || fileName.contains("/") || fileName.contains("\\")) {
            throw new FileAccessDeniedException("Ungültiger Dateiname.");
        }

        if (!SAFE_FILENAME_PATTERN.matcher(fileName).matches()) {
            throw new FileAccessDeniedException("Ungültiger Dateiname.");
        }
    }
}
