package com.example.filedownload.controller;

import com.example.filedownload.service.FileStorageService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.Resource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Endpoint für den sicheren Datei-Download.
 *
 * Die gesamte sicherheitsrelevante Logik (Validierung, Pfadauflösung,
 * Zugriffskontrolle) ist bewusst NICHT hier, sondern zentral im
 * FileStorageService implementiert (Single Responsibility +
 * Wiederverwendbarkeit gemäß OWASP-Empfehlung).
 *
 * Hinweis: In produktiven Systemen sollte dieser Endpoint zusätzlich
 * durch Spring Security abgesichert werden (Authentifizierung,
 * Autorisierung je nach Benutzerrolle, Rate Limiting), um weitere
 * OWASP-Top-10-Risiken (z.B. fehlende Authentifizierung) abzudecken.
 */
@RestController
public class FileDownloadController {

    private static final Logger log = LoggerFactory.getLogger(FileDownloadController.class);

    private final FileStorageService fileStorageService;

    public FileDownloadController(FileStorageService fileStorageService) {
        this.fileStorageService = fileStorageService;
    }

    @GetMapping("/api/files/download")
    public ResponseEntity<Resource> downloadFile(@RequestParam("file") String file) {

        Resource resource = fileStorageService.loadFileAsResource(file);

        String downloadFileName = resource.getFilename();
        // Fallback, falls getFilename() aus irgendeinem Grund null liefert.
        if (downloadFileName == null || downloadFileName.isBlank()) {
            downloadFileName = "download";
        }

        log.info("File download served successfully.");

        return ResponseEntity.ok()
                .contentType(MediaType.APPLICATION_OCTET_STREAM)
                .header(HttpHeaders.CONTENT_DISPOSITION,
                        "attachment; filename=\"" + downloadFileName + "\"")
                .body(resource);
    }
}
