"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.filedownload.controller;

import com.example.filedownload.exception.FileAccessDeniedException;
import com.example.filedownload.exception.FileNotFoundServiceException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Zentrale Fehlerbehandlung.
 *
 * Wichtig: Es werden ausschließlich generische, für den Client
 * verständliche Meldungen zurückgegeben. Interne Details wie
 * absolute Pfade, Stacktraces oder Systeminformationen werden
 * NICHT in der HTTP-Antwort preisgegeben (Vermeidung von CWE-200).
 * Details werden stattdessen serverseitig geloggt.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(FileAccessDeniedException.class)
    public ResponseEntity<String> handleAccessDenied(FileAccessDeniedException ex) {
        log.warn("Zugriff verweigert: {}", ex.getMessage());
        return ResponseEntity.status(HttpStatus.FORBIDDEN)
                .body("Zugriff auf die angeforderte Ressource ist nicht erlaubt.");
    }

    @ExceptionHandler(FileNotFoundServiceException.class)
    public ResponseEntity<String> handleNotFound(FileNotFoundServiceException ex) {
        log.info("Datei nicht gefunden: {}", ex.getMessage());
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body("Die angeforderte Datei wurde nicht gefunden.");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<String> handleGeneric(Exception ex) {
        log.error("Unerwarteter Fehler beim Dateizugriff", ex);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body("Ein interner Fehler ist aufgetreten.");
    }
}
