Der Controller ist bewusst schlank gehalten: Er validiert nichts selbst, sondern delegiert an spezialisierte Komponenten. Dadurch bleibt er leicht testbar und die Sicherheitslogik ist zentral wiederverwendbar.

---

### 2. Zielvalidierung (Whitelist gegen Command Injection)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// TargetValidator.java
package com.example.tools.validation;

import com.example.tools.exception.InvalidTargetException;
import org.springframework.stereotype.Component;

import java.util.regex.Pattern;

@Component
public class TargetValidator {

    private static final int MAX_TARGET_LENGTH = 253;

    // Erlaubt gültige DNS-Hostnamen (RFC 1123)
    private static final Pattern HOSTNAME_PATTERN = Pattern.compile(
            "^(([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)\\.)*[a-zA-Z]{2,63}$"
    );

    // Erlaubt gültige IPv4-Adressen
    private static final Pattern IPV4_PATTERN = Pattern.compile(
            "^((25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])\\.){3}"
            + "(25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])$"
    );

    // Erlaubt gültige IPv6-Adressen (vereinfachte Form)
    private static final Pattern IPV6_PATTERN = Pattern.compile(
            "^([0-9a-fA-F]{1,4}:){1,7}[0-9a-fA-F]{1,4}$|^::1$|^::$"
    );

    /**
     * Validiert das Ziel strikt gegen eine Whitelist erlaubter Zeichen und
     * Formate. Jede Eingabe, die nicht exakt einem gültigen Hostnamen,
     * einer IPv4- oder IPv6-Adresse entspricht, wird abgelehnt. Dies
     * verhindert das Einschleusen von Shell-Metazeichen (CWE-78).
     */
    public String validate(String target) {
        if (target == null || target.isBlank()) {
            throw new InvalidTargetException("Target must not be empty.");
        }

        String trimmed = target.trim();

        if (trimmed.length() > MAX_TARGET_LENGTH) {
            throw new InvalidTargetException("Target exceeds maximum allowed length.");
        }

        boolean isValid = IPV4_PATTERN.matcher(trimmed).matches()
                || IPV6_PATTERN.matcher(trimmed).matches()
                || HOSTNAME_PATTERN.matcher(trimmed).matches();

        if (!isValid) {
            throw new InvalidTargetException(
                    "Target contains invalid characters or format. "
                    + "Only valid hostnames, IPv4, or IPv6 addresses are allowed.");
        }

        return trimmed;
    }
}
