Die Regex-Muster lassen **ausschließlich** Buchstaben, Ziffern, Punkte, Doppelpunkte und Bindestriche in gültigen Positionen zu. Zeichen wie `;`, `|`, `&`, `` ` ``, `$()`, Leerzeichen oder führende `-`/`/` (Argument-Injection) werden zuverlässig abgelehnt.

---

### 3. Count-Validierung (Schutz vor Integer Overflow)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CountValidator.java
package com.example.tools.validation;

import com.example.tools.exception.InvalidCountException;
import org.springframework.stereotype.Component;

import java.util.regex.Pattern;

@Component
public class CountValidator {

    private static final int MIN_COUNT = 1;
    private static final int MAX_COUNT = 10;

    // Begrenzung auf max. 3 Ziffern verhindert bereits vor dem Parsen
    // übermäßig lange Zahlenstrings (zusätzliche Verteidigungslinie
    // gegen CWE-190/Ressourcenerschöpfung durch das Parsen riesiger Zahlen).
    private static final Pattern COUNT_PATTERN = Pattern.compile("^\\d{1,3}$");

    public int validate(String countParam) {
        if (countParam == null || countParam.isBlank()) {
            throw new InvalidCountException("Count parameter must not be empty.");
        }

        String trimmed = countParam.trim();

        if (!COUNT_PATTERN.matcher(trimmed).matches()) {
            throw new InvalidCountException(
                    "Count must be a positive integer with at most 3 digits.");
        }

        int count;
        try {
            count = Integer.parseInt(trimmed);
        } catch (NumberFormatException e) {
            throw new InvalidCountException("Count is not a valid integer.", e);
        }

        if (count < MIN_COUNT || count > MAX_COUNT) {
            throw new InvalidCountException(
                    "Count must be between " + MIN_COUNT + " and " + MAX_COUNT + ".");
        }

        return count;
    }
}
", "fileName": "Component_2", "vulnerbility": null}, {"type": "TEXT", "text": "

Durch die Kombination aus **Regex-Längenbegrenzung** und **expliziter Bereichsprüfung** (1–10) wird zuverlässig verhindert, dass extrem große Zahlen geparst werden oder ein zu hoher `count`-Wert zu einem Ping-Flood führt.

---

### 4. Sichere Ping-Ausführung

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// PingService.java
package com.example.tools.service;

import com.example.tools.exception.PingExecutionException;
import com.example.tools.validation.CountValidator;
import com.example.tools.validation.TargetValidator;
import org.springframework.stereotype.Service;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

@Service
public class PingService {

    // Gesamtes Prozess-Timeout: verhindert, dass ein hängender Prozess
    // Ressourcen blockiert (Schutz vor DoS/Ping-Flooding, CWE-400).
    private static final long PROCESS_TIMEOUT_SECONDS = 15;

    // Timeout je einzelnem ICMP-Paket, das an den OS-Ping-Befehl übergeben wird.
    private static final long PER_PACKET_TIMEOUT_SECONDS = 2;

    // Striktes Whitelist-Pattern für Zielangaben: nur Hostnamen (RFC 1123) oder
    // IPv4-Adressen. Keine Metazeichen, kein Leerzeichen, keine Shell-Sonderzeichen.
    private static final Pattern SAFE_TARGET_PATTERN = Pattern.compile(
            "^(([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]{0,62})(\\.([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]{0,62}))*)$"
    );

    private static final int MIN_COUNT = 1;
    private static final int MAX_COUNT = 10;

    // Absolute Pfade zu den erlaubten Ping-Binaries verhindern PATH-Manipulation
    // (CWE-427: Uncontrolled Search Path Element).
    private static final String PING_BIN_WINDOWS = "C:\\Windows\\System32\\PING.EXE";
    private static final String PING_BIN_UNIX = "/bin/ping";

    private final TargetValidator targetValidator;
    private final CountValidator countValidator;

    public PingService(TargetValidator targetValidator, CountValidator countValidator) {
        this.targetValidator = targetValidator;
        this.countValidator = countValidator;
    }

    public String executePing(String rawTarget, String rawCount) {
        String target = targetValidator.validate(rawTarget);
        int count = countValidator.validate(rawCount);

        // Defense in depth: unabhängig von der externen Validator-Implementierung
        // wird hier erneut strikt gegen eine Whitelist geprüft, bevor der Wert
        // in einen OS-Befehl gelangt.
        assertSafeTarget(target);
        assertSafeCount(count);

        List<String> command = buildCommand(target, count);

        ProcessBuilder builder = new ProcessBuilder(command);
        builder.redirectErrorStream(true);

        // Keine ererbten Umgebungsvariablen an den Kindprozess weitergeben,
        // die potenziell missbraucht werden könnten.
        builder.environment().clear();

        Process process = null;
        try {
            // ProcessBuilder mit Argument-Liste startet den Prozess DIREKT,
            // ohne eine Shell zu involvieren. Dadurch werden Metazeichen
            // wie ;, |, &, $() nicht interpretiert (IDS07-J-konform).
            process = builder.start();

            boolean finished = process.waitFor(PROCESS_TIMEOUT_SECONDS, TimeUnit.SECONDS);
            if (!finished) {
                process.destroyForcibly();
                throw new PingExecutionException("Ping command timed out and was terminated.");
            }

            String output = readProcessOutput(process);

            if (process.exitValue() != 0 && output.isBlank()) {
                throw new PingExecutionException(
                        "Ping command failed with exit code " + process.exitValue());
            }

            return output;

        } catch (IOException e) {
            throw new PingExecutionException("Failed to execute ping command.", e);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new PingExecutionException("Ping command was interrupted.", e);
        } finally {
            if (process != null && process.isAlive()) {
                process.destroyForcibly();
            }
        }
    }

    private void assertSafeTarget(String target) {
        if (target == null || target.isBlank() || target.length() > 253
                || !SAFE_TARGET_PATTERN.matcher(target).matches()) {
            throw new PingExecutionException("Invalid target after validation.");
        }
    }

    private void assertSafeCount(int count) {
        if (count < MIN_COUNT || count > MAX_COUNT) {
            throw new PingExecutionException("Invalid count after validation.");
        }
    }

    private List<String> buildCommand(String target, int count) {
        String os = System.getProperty("os.name", "").toLowerCase(Locale.ROOT);
        List<String> command = new ArrayList<>();

        boolean isWindows = os.contains("win");
        command.add(isWindows ? PING_BIN_WINDOWS : PING_BIN_UNIX);

        if (isWindows) {
            command.add("-n");
            command.add(String.valueOf(count));
            command.add("-w");
            command.add(String.valueOf(PER_PACKET_TIMEOUT_SECONDS * 1000));
        } else {
            command.add("-c");
            command.add(String.valueOf(count));
            command.add("-W");
            command.add(String.valueOf(PER_PACKET_TIMEOUT_SECONDS));
        }

        // target wurde bereits gegen eine strikte Whitelist validiert und
        // wird als separates Argument übergeben, nie als Teil eines
        // zusammengesetzten Shell-Strings.
        command.add(target);
        return Collections.unmodifiableList(command);
    }

    private String readProcessOutput(Process process) throws IOException {
        StringBuilder output = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line).append(System.lineSeparator());
            }
        }
        return output.toString();
    }
}
