### 7. Zentrales Exception-Handling

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.tools.exception;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(InvalidTargetException.class)
    public ResponseEntity<String> handleInvalidTarget(InvalidTargetException ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(ex.getMessage());
    }

    @ExceptionHandler(InvalidCountException.class)
    public ResponseEntity<String> handleInvalidCount(InvalidCountException ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(ex.getMessage());
    }

    @ExceptionHandler(RateLimitExceededException.class)
    public ResponseEntity<String> handleRateLimit(RateLimitExceededException ex) {
        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body(ex.getMessage());
    }

    @ExceptionHandler(PingExecutionException.class)
    public ResponseEntity<String> handlePingExecution(PingExecutionException ex) {
        // Interne Details werden bewusst nicht an den Client weitergegeben,
        // um Information Disclosure (CWE-209) zu vermeiden.
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body("Ping execution failed. Please contact support if the problem persists.");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<String> handleGeneral(Exception ex) {
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body("An unexpected error occurred.");
    }
}
