## 6. Service-Schicht (Defense-in-Depth Validierung + Sanitizing)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GuestbookService.java
package com.example.guestbook.service;

import com.example.guestbook.dto.GuestbookEntryRequest;
import com.example.guestbook.dto.GuestbookEntryResponse;
import com.example.guestbook.entity.GuestbookEntry;
import com.example.guestbook.exception.InvalidGuestbookInputException;
import com.example.guestbook.repository.GuestbookEntryRepository;
import org.owasp.html.HtmlPolicyBuilder;
import org.owasp.html.PolicyFactory;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.List;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

@Service
public class GuestbookService {

    private static final Logger LOGGER = LoggerFactory.getLogger(GuestbookService.class);

    // Strikte Policy: keinerlei HTML-Tags werden akzeptiert, alles wird als reiner Text behandelt.
    private static final PolicyFactory PLAIN_TEXT_POLICY = new HtmlPolicyBuilder().toFactory();

    // Zusätzliche serverseitige Prüfung (Defense-in-Depth), unabhängig von der Bean-Validation
    // am Controller-Rand, falls diese z. B. durch einen internen Aufruf umgangen wird.
    private static final Pattern SAFE_NAME_PATTERN = Pattern.compile("^[\\p{L}0-9 .,'\\-]{1,100}$");
    private static final Pattern SAFE_TEXT_PATTERN = Pattern.compile("^[\\p{L}\\p{N}\\s.,!?'\\-:;()\"]{1,1000}$");

    private final GuestbookEntryRepository repository;

    public GuestbookService(GuestbookEntryRepository repository) {
        this.repository = repository;
    }

    public GuestbookEntryResponse createEntry(GuestbookEntryRequest request, Authentication authentication) {
        String rawName = request.getName();
        String rawText = request.getText();

        if (!SAFE_NAME_PATTERN.matcher(rawName).matches()) {
            LOGGER.warn("Guestbook-Eintrag mit ungültigem Namen abgelehnt, Benutzer={}", authentication.getName());
            throw new InvalidGuestbookInputException("Name enthält nicht erlaubte Zeichen");
        }
        if (!SAFE_TEXT_PATTERN.matcher(rawText).matches()) {
            LOGGER.warn("Guestbook-Eintrag mit ungültigem Text abgelehnt, Benutzer={}", authentication.getName());
            throw new InvalidGuestbookInputException("Text enthält nicht erlaubte Zeichen");
        }

        // Zusätzliches Sanitizing vor dem Persistieren (Defense-in-Depth gegen Stored XSS,
        // CWE-79), auch wenn die Werte durch die Allowlist bereits als reiner Text vorliegen.
        String sanitizedName = PLAIN_TEXT_POLICY.sanitize(rawName);
        String sanitizedText = PLAIN_TEXT_POLICY.sanitize(rawText);

        GuestbookEntry entry = new GuestbookEntry(sanitizedName, sanitizedText, Instant.now());
        GuestbookEntry saved = repository.save(entry);

        // Parametrisiertes Logging: Nutzereingaben werden nicht per String-Konkatenation
        // in die Log-Message eingefügt (verhindert Log Injection, CWE-93).
        LOGGER.info("Guestbook-Eintrag {} von Benutzer {} erstellt", saved.getId(), authentication.getName());

        return toResponse(saved);
    }

    public List<GuestbookEntryResponse> getAllEntries() {
        return repository.findAllOrderedByCreatedAtDesc().stream()
                .map(this::toResponse)
                .collect(Collectors.toList());
    }

    private GuestbookEntryResponse toResponse(GuestbookEntry entry) {
        return new GuestbookEntryResponse(entry.getId(), entry.getName(), entry.getText(), entry.getCreatedAt());
    }
}
", "fileName": "Component_5", "vulnerbility": null}, {"type": "TEXT", "text": "

Der Service prüft die Eingaben **erneut serverseitig** (nicht nur clientseitig oder nur am Controller-Rand) und wendet zusätzlich den `OWASP Java HTML Sanitizer` mit einer sehr restriktiven Policy an, die jegliches Markup entfernt. Dadurch bleibt die Anwendung auch dann sicher, wenn der Service künftig aus einem anderen Kontext (z. B. Batch-Import, interner Service-Call) ohne vorherige Bean-Validation aufgerufen wird.

---

## 7. Controller

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GuestbookController.java
package com.example.guestbook.controller;

import com.example.guestbook.dto.GuestbookEntryRequest;
import com.example.guestbook.dto.GuestbookEntryResponse;
import com.example.guestbook.service.GuestbookService;
import jakarta.validation.Valid;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseBody;

import java.util.List;

@Controller
@RequestMapping("/guestbook")
public class GuestbookController {

    private static final Logger LOGGER = LoggerFactory.getLogger(GuestbookController.class);

    private final GuestbookService guestbookService;

    public GuestbookController(GuestbookService guestbookService) {
        this.guestbookService = guestbookService;
    }

    /**
     * Legt einen neuen Guestbook-Eintrag an.
     * Erfordert eine authentifizierte Sitzung (siehe SecurityConfig) sowie einen gültigen
     * CSRF-Token, der über den Cookie "XSRF-TOKEN" bezogen und im Header "X-XSRF-TOKEN"
     * mitgesendet werden muss.
     */
    @PostMapping(value = "/entries", consumes = "application/json", produces = "application/json")
    @ResponseBody
    public ResponseEntity<GuestbookEntryResponse> createEntry(
            @Valid @RequestBody GuestbookEntryRequest request,
            Authentication authentication) {

        GuestbookEntryResponse response = guestbookService.createEntry(request, authentication);
        LOGGER.info("Neuer Guestbook-Eintrag {} erstellt", response.getId());
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }

    /**
     * Zeigt alle vorhandenen Guestbook-Einträge als HTML-Seite an.
     * Der Zugriff ist nur authentifizierten Benutzern mit Rolle USER erlaubt.
     */
    @GetMapping
    public String viewGuestbook(Model model, Authentication authentication) {
        List<GuestbookEntryResponse> entries = guestbookService.getAllEntries();
        model.addAttribute("entries", entries);
        model.addAttribute("username", authentication.getName());
        LOGGER.info("Guestbook von Benutzer {} aufgerufen", authentication.getName());
        return "guestbook";
    }
}
", "fileName": "Component_6", "vulnerbility": null}, {"type": "TEXT", "text": "

Der Controller ist bewusst schlank gehalten: Die eigentliche Validierung erfolgt bereits über `@Valid` (Bean Validation) auf dem DTO, die Autorisierung wird zentral über die Spring-Security-Konfiguration erzwungen (kein manuelles, fehleranfälliges Rollen-Handling im Controller-Code).

---

## 8. Zentrale Exception-Behandlung (keine Informationspreisgabe)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.guestbook.exception;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;

@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger LOGGER = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> handleValidationException(MethodArgumentNotValidException ex) {
        LOGGER.warn("Anfrage aufgrund von Validierungsfehlern abgelehnt: {} Fehler",
                ex.getBindingResult().getErrorCount());
        return buildErrorResponse(HttpStatus.BAD_REQUEST, "Ungültige Eingabedaten.");
    }

    @ExceptionHandler(InvalidGuestbookInputException.class)
    public ResponseEntity<Map<String, Object>> handleInvalidGuestbookInput(InvalidGuestbookInputException ex) {
        LOGGER.warn("Guestbook-Eintrag abgelehnt: {}", ex.getMessage());
        return buildErrorResponse(HttpStatus.BAD_REQUEST, "Ungültige Eingabedaten.");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, Object>> handleGenericException(Exception ex) {
        // Interne Details (Stacktrace, Exception-Klasse etc.) werden bewusst NICHT
        // an den Client zurückgegeben, um Information Disclosure (CWE-209) zu vermeiden.
        LOGGER.error("Unerwarteter Fehler aufgetreten", ex);
        return buildErrorResponse(HttpStatus.INTERNAL_SERVER_ERROR, "Ein unerwarteter Fehler ist aufgetreten.");
    }

    private ResponseEntity<Map<String, Object>> buildErrorResponse(HttpStatus status, String message) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", status.value());
        body.put("error", message);
        return ResponseEntity.status(status).body(body);
    }
}
", "fileName": "Component_7", "vulnerbility": null}, {"type": "TEXT", "text": "

