package com.example.customersearch.validation;

import com.example.customersearch.exception.InvalidSearchException;

import java.util.regex.Pattern;

/**
 * Zentrale Validierungs- und Sanitisierungslogik für Suchparameter.
 * Dient als zusätzliche Verteidigungslinie (Defense in Depth) neben
 * der Bean-Validation auf dem Request-DTO.
 */
public final class SearchInputValidator {

    // Erlaubt Buchstaben (inkl. Umlaute), Ziffern, Leerzeichen sowie @ . - '
    private static final Pattern ALLOWED_PATTERN =
            Pattern.compile("^[\\p{L}0-9 .@'\\-]{1,100}$");

    private SearchInputValidator() {
        // Utility-Klasse, keine Instanziierung
    }

    public static String validateAndSanitize(String rawInput) {
        if (rawInput == null || rawInput.isBlank()) {
            throw new InvalidSearchException("Der Suchparameter darf nicht leer sein.");
        }

        String trimmed = rawInput.trim();

        if (!ALLOWED_PATTERN.matcher(trimmed).matches()) {
            throw new InvalidSearchException(
                    "Der Suchparameter enthält unzulässige Zeichen oder ist zu lang.");
        }

        return trimmed;
    }

    /**
     * Maskiert SQL-LIKE-Wildcards (%, _ und \), damit sie im JPQL-LIKE
     * ausschließlich als literale Zeichen interpretiert werden.
     */
    public static String escapeLikeWildcards(String input) {
        return input
                .replace("\\", "\\\\")
                .replace("%", "\\%")
                .replace("_", "\\_");
    }
}
