package com.example.customersearch.repository;

import com.example.customersearch.entity.Customer;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.List;

public interface CustomerRepository extends JpaRepository<Customer, Long> {

    /**
     * Sucht Kunden anhand von Name, E-Mail oder Stadt.
     * Das Muster (pattern) wird vom Aufrufer bereits maskiert (LIKE-Escaping),
     * sodass Sonderzeichen wie %, _ und \ nicht als SQL-Wildcards missbraucht
     * werden können. Die Bindung erfolgt ausschließlich über einen benannten
     * Parameter (:pattern), wodurch klassische SQL-Injection (CWE-89)
     * ausgeschlossen ist.
     */
    @Query("SELECT c FROM Customer c WHERE "
            + "LOWER(c.name) LIKE LOWER(:pattern) ESCAPE '\\' OR "
            + "LOWER(c.email) LIKE LOWER(:pattern) ESCAPE '\\' OR "
            + "LOWER(c.city) LIKE LOWER(:pattern) ESCAPE '\\'")
    List<Customer> searchByNameEmailOrCity(@Param("pattern") String pattern);
}
