package com.example.customersearch.service;

import com.example.customersearch.dto.CustomerDTO;
import com.example.customersearch.entity.Customer;
import com.example.customersearch.repository.CustomerRepository;
import com.example.customersearch.validation.SearchInputValidator;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class CustomerSearchServiceImpl implements CustomerSearchService {

    private final CustomerRepository customerRepository;

    public CustomerSearchServiceImpl(CustomerRepository customerRepository) {
        this.customerRepository = customerRepository;
    }

    @Override
    public List<CustomerDTO> searchCustomers(String rawSearchTerm) {
        // 1. Validierung/Sanitisierung als zweite Verteidigungslinie
        String sanitized = SearchInputValidator.validateAndSanitize(rawSearchTerm);

        // 2. LIKE-Wildcards maskieren, damit % und _ nicht als Steuerzeichen wirken
        String escaped = SearchInputValidator.escapeLikeWildcards(sanitized);
        String pattern = "%" + escaped + "%";

        // 3. Ausschließlich parametrisierte Query verwenden (CWE-89 sicher)
        List<Customer> customers = customerRepository.searchByNameEmailOrCity(pattern);

        // 4. Mapping auf DTOs, damit interne Entity-Struktur nicht direkt serialisiert wird
        return customers.stream()
                .map(c -> new CustomerDTO(c.getId(), c.getName(), c.getEmail(), c.getCity()))
                .toList();
    }
}
