package com.example.export;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.Resource;
import org.springframework.core.io.UrlResource;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.MalformedURLException;
import java.nio.file.Files;
import java.nio.file.NoSuchFileException;
import java.nio.file.Path;
import java.nio.file.Paths;

/**
 * Kapselt den gesamten sicherheitsrelevanten Zugriff auf das Exportverzeichnis.
 * Diese Klasse ist die EINZIGE Stelle, an der Dateisystempfade aufgelöst werden,
 * um Konsistenz der Sicherheitsprüfungen zu gewährleisten.
 */
@Service
public class FileExportService {

    private static final Logger log = LoggerFactory.getLogger(FileExportService.class);

    private final Path exportsBaseDirectory;

    public FileExportService(@Value("${app.exports.directory}") String exportsDirectory) {
        Path base = Paths.get(exportsDirectory).toAbsolutePath().normalize();
        try {
            // toRealPath() löst Symlinks auf und schlägt fehl, falls das Verzeichnis nicht existiert.
            this.exportsBaseDirectory = base.toRealPath();
        } catch (IOException e) {
            throw new IllegalStateException(
                    "Configured exports directory does not exist or is not accessible.", e);
        }
    }

    public ExportedFile loadFile(String filenameParam) {

        // 1. Whitelist-Validierung des rohen Eingabeparameters (CWE-22)
        if (!FilenameValidator.isValid(filenameParam)) {
            log.warn("Rejected export request with invalid filename parameter (sanitized): {}",
                    sanitizeForLog(filenameParam));
            throw new InvalidFilenameException();
        }

        // 2. Kandidatenpfad relativ zum Exportverzeichnis auflösen und normalisieren
        Path candidate = exportsBaseDirectory.resolve(filenameParam).normalize();

        if (!candidate.startsWith(exportsBaseDirectory)) {
            log.warn("Path traversal attempt detected for filename (sanitized): {}",
                    sanitizeForLog(filenameParam));
            throw new InvalidFilenameException();
        }

        // 3. Realen Pfad auflösen (folgt Symlinks) und erneut gegen das Basisverzeichnis prüfen (CWE-36, CWE-59/61)
        Path realCandidate;
        try {
            realCandidate = candidate.toRealPath();
        } catch (NoSuchFileException e) {
            throw new ExportFileNotFoundException();
        } catch (IOException e) {
            log.warn("Unable to resolve real path for export request (sanitized): {}",
                    sanitizeForLog(filenameParam));
            throw new ExportFileNotFoundException();
        }

        if (!realCandidate.startsWith(exportsBaseDirectory) || !Files.isRegularFile(realCandidate)) {
            log.warn("Resolved path escapes exports directory or is not a regular file (sanitized): {}",
                    sanitizeForLog(filenameParam));
            throw new ExportFileNotFoundException();
        }

        if (!Files.isReadable(realCandidate)) {
            throw new ExportFileNotFoundException();
        }

        Resource resource;
        try {
            resource = new UrlResource(realCandidate.toUri());
        } catch (MalformedURLException e) {
            throw new ExportFileNotFoundException();
        }

        if (!resource.exists() || !resource.isReadable()) {
            throw new ExportFileNotFoundException();
        }

        // Nur der validierte, aus dem realen Pfad extrahierte Dateiname wird nach außen gegeben (CWE-200)
        String safeFilename = realCandidate.getFileName().toString();
        MediaType mediaType = resolveMediaType(realCandidate);

        return new ExportedFile(resource, safeFilename, mediaType);
    }

    private MediaType resolveMediaType(Path file) {
        try {
            String contentType = Files.probeContentType(file);
            if (contentType != null) {
                return MediaType.parseMediaType(contentType);
            }
        } catch (IOException | IllegalArgumentException ignored) {
            // Fallback unten
        }
        return MediaType.APPLICATION_OCTET_STREAM;
    }

    /**
     * Entfernt CR/LF aus Benutzereingaben vor dem Logging, um Log-Injection (CWE-117) zu verhindern.
     */
    private String sanitizeForLog(String input) {
        if (input == null) {
            return "null";
        }
        return input.replaceAll("[\\r\\n\\t]", "_");
    }
}
