package com.example.export;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Zentrales Error-Handling nur für den ExportController.
 * Gibt bewusst knappe, generische Fehlermeldungen zurück (CWE-209),
 * um keine internen Details (Pfade, Stacktraces, Systeminformationen) preiszugeben.
 */
@RestControllerAdvice(assignableTypes = ExportController.class)
public class ExportExceptionHandler {

    @ExceptionHandler(InvalidFilenameException.class)
    public ProblemDetail handleInvalidFilename(InvalidFilenameException ex) {
        return ProblemDetail.forStatusAndDetail(
                HttpStatus.BAD_REQUEST, "The requested file could not be processed.");
    }

    @ExceptionHandler(ExportFileNotFoundException.class)
    public ProblemDetail handleFileNotFound(ExportFileNotFoundException ex) {
        return ProblemDetail.forStatusAndDetail(
                HttpStatus.NOT_FOUND, "The requested file does not exist.");
    }
}
