"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecurityConfig.java
package com.example.export;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;

/**
 * Erzwingt Authentifizierung für den Export-Endpoint (Deny-by-default, A01:2025).
 * CORS wird bewusst NICHT global für diesen Endpoint geöffnet - es sollte,
 * falls überhaupt benötigt, restriktiv und zentral konfiguriert werden,
 * niemals über @CrossOrigin direkt am Controller.
 */
@Configuration
@EnableMethodSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http.authorizeHttpRequests(auth -> auth
                .requestMatchers("/export").authenticated()
                .anyRequest().authenticated()
        );
        // CSRF-Schutz bleibt für zustandsändernde Requests (POST/PUT/DELETE) per Default aktiv.
        // GET-Requests wie dieser Download-Endpoint sind davon standardmäßig ausgenommen.
        return http.build();
    }
}
