"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ExportController.java
package com.example.export;

import org.springframework.core.io.Resource;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.nio.charset.StandardCharsets;

/**
 * REST-Endpoint zum sicheren Download von Exportdateien.
 * Die gesamte sicherheitsrelevante Logik liegt in FileExportService -
 * der Controller selbst enthält keine Pfad- oder Dateisystemzugriffe.
 */
@RestController
@RequestMapping("/export")
public class ExportController {

    private final FileExportService fileExportService;

    public ExportController(FileExportService fileExportService) {
        this.fileExportService = fileExportService;
    }

    @GetMapping
    @PreAuthorize("isAuthenticated()")
    public ResponseEntity<Resource> exportFile(@RequestParam("filename") String filename) {

        FileExportService.ExportedFile exportedFile = fileExportService.loadFile(filename);
        Resource resource = exportedFile.resource();

        // Sicherer Content-Disposition-Header: RFC-5987-konforme Kodierung des
        // bereits validierten Dateinamens, verhindert Header-Injection und
        // gibt niemals interne Serverpfade preis (CWE-200).
        ContentDisposition contentDisposition = ContentDisposition.attachment()
                .filename(exportedFile.safeFilename(), StandardCharsets.UTF_8)
                .build();

        HttpHeaders headers = new HttpHeaders();
        headers.setContentDisposition(contentDisposition);
        headers.setContentType(exportedFile.mediaType());
        headers.set(HttpHeaders.CACHE_CONTROL, "no-store");
        headers.set(HttpHeaders.X_CONTENT_TYPE_OPTIONS, "nosniff");

        return new ResponseEntity<>(resource, headers, HttpStatus.OK);
    }
}
