### 2. Validator-Interface

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectValidator.java
package com.example.redirect.validation;

import java.net.URI;

/**
 * Vertrag für die Validierung von Redirect-Ziel-URLs gegen eine Allow-List.
 */
public interface RedirectValidator {

    /**
     * Prüft die übergebene URL und liefert bei Erfolg eine sichere URI zurück.
     *
     * @param redirectUrl der vom Client übergebene, nicht vertrauenswürdige Wert
     * @return validierte, sichere URI
     * @throws com.example.redirect.exception.InvalidRedirectUrlException wenn die URL nicht erlaubt ist
     */
    URI validate(String redirectUrl);
}
", "fileName": "Component_1", "vulnerbility": null}, {"type": "TEXT", "text": "

### 3. Allow-List-Implementierung des Validators

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// AllowListRedirectValidator.java
package com.example.redirect.validation;

import com.example.redirect.config.RedirectAllowListProperties;
import com.example.redirect.exception.InvalidRedirectUrlException;
import org.springframework.stereotype.Component;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Set;

@Component
public class AllowListRedirectValidator implements RedirectValidator {

    private final Set<String> allowedRedirectUrls;

    public AllowListRedirectValidator(RedirectAllowListProperties properties) {
        this.allowedRedirectUrls = Set.copyOf(properties.getAllowedUrls());
    }

    @Override
    public URI validate(String redirectUrl) {
        if (redirectUrl == null || redirectUrl.isBlank()) {
            throw new InvalidRedirectUrlException("redirectUrl darf nicht leer sein.");
        }

        String normalized = redirectUrl.trim();

        // 1. Strikte Allow-List-Prüfung: nur exakt konfigurierte Ziele sind erlaubt (CWE-20)
        if (!allowedRedirectUrls.contains(normalized)) {
            throw new InvalidRedirectUrlException(
                    "redirectUrl ist nicht in der konfigurierten Allow-List enthalten: " + normalized);
        }

        // 2. Defense-in-Depth: syntaktische Prüfung, auch wenn der Wert bereits gelistet ist
        URI uri;
        try {
            uri = new URI(normalized);
        } catch (URISyntaxException e) {
            throw new InvalidRedirectUrlException(
                    "redirectUrl ist syntaktisch keine gültige URI: " + normalized);
        }

        if (!uri.isAbsolute() || uri.getHost() == null) {
            throw new InvalidRedirectUrlException(
                    "redirectUrl muss eine absolute URL mit Host sein: " + normalized);
        }

        if (!"https".equalsIgnoreCase(uri.getScheme())) {
            throw new InvalidRedirectUrlException(
                    "Nur https-Redirects sind zulässig: " + normalized);
        }

        if (uri.getUserInfo() != null) {
            throw new InvalidRedirectUrlException(
                    "redirectUrl darf keine Userinfo-Komponente enthalten: " + normalized);
        }

        return uri;
    }
}
", "fileName": "Component_2", "vulnerbility": null}, {"type": "TEXT", "text": "

Die doppelte Prüfung (Allow-List-Mitgliedschaft **und** erneutes Parsen) ist bewusst redundant: Sollte die Allow-List versehentlich einen unsicheren Eintrag enthalten (z. B. durch Fehlkonfiguration), fängt die zweite Prüfschicht typische Angriffsmuster wie `https://trusted.com@evil.com` (Userinfo-Trick) oder nicht-https-Schemata trotzdem ab.

