package com.example.redirect.ratelimit;

/**
 * Vertrag für eine einfache Rate-Limiting-Strategie pro Client-Identifier.
 */
public interface RateLimiterService {

    /**
     * Prüft, ob der Client sein Kontingent überschritten hat.
     *
     * @param clientId eindeutiger Identifier des Clients (z. B. IP-Adresse)
     * @throws com.example.redirect.exception.RateLimitExceededException wenn das Limit erreicht wurde
     */
    void checkRateLimit(String clientId);
}
