### 6. In-Memory Rate-Limiter-Implementierung

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// InMemoryRateLimiterService.java
package com.example.redirect.ratelimit;

import com.example.redirect.exception.RateLimitExceededException;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Einfacher Sliding-Window-Rate-Limiter pro Client-Identifier (CWE-400).
 *
 * Hinweis: Diese In-Memory-Implementierung eignet sich für Einzelinstanzen.
 * In verteilten Deployments sollte ein zentraler Store (z. B. Redis mit Bucket4j)
 * verwendet werden, damit das Limit instanzübergreifend gilt.
 */
@Service
public class InMemoryRateLimiterService implements RateLimiterService {

    private static final int MAX_REQUESTS_PER_WINDOW = 20;
    private static final Duration WINDOW = Duration.ofMinutes(1);
    private static final Duration STALE_ENTRY_TTL = Duration.ofMinutes(5);

    private final ConcurrentHashMap<String, Deque<Instant>> requestLog = new ConcurrentHashMap<>();

    @Override
    public void checkRateLimit(String clientId) {
        Instant now = Instant.now();
        Deque<Instant> timestamps = requestLog.computeIfAbsent(clientId, key -> new ArrayDeque<>());

        synchronized (timestamps) {
            evictOutsideWindow(timestamps, now);

            if (timestamps.size() >= MAX_REQUESTS_PER_WINDOW) {
                throw new RateLimitExceededException(
                        "Rate-Limit für Client überschritten: " + clientId);
            }

            timestamps.addLast(now);
        }
    }

    private void evictOutsideWindow(Deque<Instant> timestamps, Instant now) {
        while (!timestamps.isEmpty()
                && Duration.between(timestamps.peekFirst(), now).compareTo(WINDOW) > 0) {
            timestamps.pollFirst();
        }
    }

    /**
     * Bereinigt periodisch veraltete Client-Einträge, um unbegrenztes
     * Speicherwachstum (Memory Leak) zu vermeiden.
     */
    @Scheduled(fixedRate = 300_000)
    void cleanupStaleEntries() {
        Instant now = Instant.now();
        requestLog.entrySet().removeIf(entry -> {
            Deque<Instant> timestamps = entry.getValue();
            synchronized (timestamps) {
                return timestamps.isEmpty()
                        || Duration.between(timestamps.peekLast(), now).compareTo(STALE_ENTRY_TTL) > 0;
            }
        });
    }
}
