### 8. Der REST-Controller

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectController.java
package com.example.redirect.controller;

import com.example.redirect.ratelimit.RateLimiterService;
import com.example.redirect.validation.RedirectValidator;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.net.URI;

@RestController
@RequestMapping("/api/redirect")
public class RedirectController {

    private final RedirectValidator redirectValidator;
    private final RateLimiterService rateLimiterService;

    public RedirectController(RedirectValidator redirectValidator,
                               RateLimiterService rateLimiterService) {
        this.redirectValidator = redirectValidator;
        this.rateLimiterService = rateLimiterService;
    }

    @GetMapping
    public ResponseEntity<Void> redirect(@RequestParam("redirectUrl") String redirectUrl,
                                          HttpServletRequest request) {

        // 1. Missbrauchsschutz zuerst prüfen, bevor Validierungsaufwand betrieben wird
        rateLimiterService.checkRateLimit(resolveClientId(request));

        // 2. Strikte Allow-List-Validierung der Ziel-URL
        URI safeRedirectUri = redirectValidator.validate(redirectUrl);

        // 3. Redirect ausschließlich mit dem validierten Wert erzeugen
        return ResponseEntity.status(HttpStatus.FOUND)
                .location(safeRedirectUri)
                .build();
    }

    /**
     * Ermittelt den Client-Identifier für das Rate-Limiting.
     *
     * Hinweis: {@code X-Forwarded-For} wird bewusst NICHT ausgewertet, da dieser
     * Header vom Client frei gesetzt werden kann und ohne einen vertrauenswürdigen,
     * korrekt konfigurierten Reverse-Proxy das Rate-Limiting aushebeln würde.
     * Läuft die Anwendung hinter einem Proxy, sollte stattdessen der von diesem
     * Proxy gesetzte, geprüfte Header verwendet werden.
     */
    private String resolveClientId(HttpServletRequest request) {
        return request.getRemoteAddr();
    }
}
", "fileName": "Component_7", "vulnerbility": null}, {"type": "TEXT", "text": "

### 9. Zentrales Exception-Handling

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectExceptionHandler.java
package com.example.redirect.exception;

import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class RedirectExceptionHandler {

    @ExceptionHandler(InvalidRedirectUrlException.class)
    public ResponseEntity<ProblemDetail> handleInvalidRedirect(InvalidRedirectUrlException ex) {
        // Bewusst generische Meldung ohne Reflektion des Original-Inputs,
        // um Injection-/XSS-Risiken über Fehlermeldungen zu vermeiden.
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(
                HttpStatus.BAD_REQUEST,
                "Das angegebene Redirect-Ziel ist nicht zulässig.");
        problem.setTitle("Ungültige redirectUrl");
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(problem);
    }

    @ExceptionHandler(RateLimitExceededException.class)
    public ResponseEntity<ProblemDetail> handleRateLimit(RateLimitExceededException ex) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(
                HttpStatus.TOO_MANY_REQUESTS,
                "Zu viele Anfragen. Bitte versuchen Sie es später erneut.");
        problem.setTitle("Rate-Limit überschritten");
        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body(problem);
    }
}
