### 10. Zentrale Konfiguration (Aktivierung von Properties & Scheduling)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectSecurityConfig.java
package com.example.redirect.config;

import org.springframework.boot.context.properties.EnableConfigurationProperties;
