"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FingerprintController.java
package com.example.fingerprint;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST controller exposing the /fingerprint endpoint.
 * Delegates all cryptographic logic to FingerprintService and performs
 * only input validation here.
 */
@RestController
@Validated
public class FingerprintController {

    private final FingerprintService fingerprintService;

    public FingerprintController(FingerprintService fingerprintService) {
        this.fingerprintService = fingerprintService;
    }

    @GetMapping("/fingerprint")
    public ResponseEntity<FingerprintResponse> fingerprint(
            @RequestParam("value")
            @NotBlank(message = "value must not be blank")
            @Size(max = 2048, message = "value must not exceed 2048 characters")
            String value) {

        String hash = fingerprintService.generateFingerprint(value);
        return ResponseEntity.ok(new FingerprintResponse(hash));
    }
}
