package com.example.fingerprint;

/**
 * Service abstraction for generating cryptographic fingerprints.
 */
public interface FingerprintService {

    /**
     * Generates a fixed-length, cryptographically secure fingerprint for the given value.
     *
     * @param value the input value to fingerprint
     * @return a hex-encoded fingerprint string of fixed length
     */
    String generateFingerprint(String value);
}
