"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FingerprintServiceImpl.java
package com.example.fingerprint;

import org.springframework.stereotype.Service;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * Computes fingerprints using HMAC-SHA256 instead of a bare hash function.
 * HMAC is used specifically to prevent hash length-extension attacks that
 * would be possible with a naive SHA-256(secret || message) construction.
 * The output has a fixed length, independent of the input, and no
 * predictable/static salt is ever used - the key is externally supplied
 * random material (see HmacKeyProvider).
 */
@Service
public class FingerprintServiceImpl implements FingerprintService {

    private static final String HMAC_ALGORITHM = "HmacSHA256";

    /** Minimum retained output bytes to preserve at least 128 bits of security margin. */
    private static final int MIN_OUTPUT_BYTES = 16;

    /** Fixed output length returned to callers (full HMAC-SHA256 = 32 bytes / 256 bit). */
    private static final int OUTPUT_BYTES = 32;

    private final HmacKeyProvider keyProvider;

    public FingerprintServiceImpl(HmacKeyProvider keyProvider) {
        this.keyProvider = keyProvider;
    }

    @Override
    public String generateFingerprint(String value) {
        try {
            Mac mac = Mac.getInstance(HMAC_ALGORITHM);
            SecretKeySpec keySpec = new SecretKeySpec(keyProvider.getKey(), HMAC_ALGORITHM);
            mac.init(keySpec);

            byte[] rawHmac = mac.doFinal(value.getBytes(StandardCharsets.UTF_8));

            int length = Math.min(OUTPUT_BYTES, rawHmac.length);
            if (length < MIN_OUTPUT_BYTES) {
                // Defensive check; should never occur with HmacSHA256 (32 byte output).
                throw new FingerprintException("Unexpected HMAC output length");
            }

            byte[] truncated = new byte[length];
            System.arraycopy(rawHmac, 0, truncated, 0, length);

            return HexFormat.of().formatHex(truncated);
        } catch (NoSuchAlgorithmException | InvalidKeyException e) {
            // Never propagate low-level crypto/algorithm details to the caller (ERR01-J / CWE-209).
            throw new FingerprintException("Unable to compute fingerprint", e);
        }
    }
}
