"}, {"type": "CODE_BLOCK", "language": "java", "content": "// HmacKeyProvider.java
package com.example.fingerprint;

import jakarta.annotation.PostConstruct;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.util.Base64;

/**
 * Loads and validates the HMAC secret key from externalized configuration
 * (environment variable / secret store), never from a hard-coded or
 * predictable default value. Fails fast at startup if the configuration
 * is missing or insufficiently strong.
 *
 * Example provisioning:
 *   export FINGERPRINT_HMAC_SECRET=$(openssl rand -base64 32)
 *   # application.yml: fingerprint.hmac.secret: ${FINGERPRINT_HMAC_SECRET}
 */
@Component
public class HmacKeyProvider {

    @Value("${fingerprint.hmac.secret:}")
    private String base64Secret;

    private byte[] key;

    @PostConstruct
    public void init() {
        if (base64Secret == null || base64Secret.isBlank()) {
            throw new IllegalStateException(
                "Missing required configuration property 'fingerprint.hmac.secret'. " +
                "Provide a cryptographically random, Base64-encoded secret of at least " +
                "256 bits via a secure secret store or environment variable " +
                "(FINGERPRINT_HMAC_SECRET)."
            );
        }

        byte[] decoded;
        try {
            decoded = Base64.getDecoder().decode(base64Secret);
        } catch (IllegalArgumentException e) {
            throw new IllegalStateException("Configured HMAC secret is not valid Base64.", e);
        }

        if (decoded.length < 32) {
            throw new IllegalStateException(
                "Configured HMAC secret is too short. At least 256 bits (32 bytes) are required."
            );
        }

        this.key = decoded;
    }

    byte[] getKey() {
        return key;
    }
}
