import java.time.Instant;

/**
 * Generic error payload returned to API clients. Contains no internal
 * implementation details, stack traces, or system information (CWE-209 mitigation).
 * The errorId can be correlated with server-side logs for diagnostics.
 */
public class ErrorResponse {

    private final String errorId;
    private final String message;
    private final Instant timestamp;

    public ErrorResponse(String errorId, String message, Instant timestamp) {
        this.errorId = errorId;
        this.message = message;
        this.timestamp = timestamp;
    }

    public String getErrorId() {
        return errorId;
    }

    public String getMessage() {
        return message;
