"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.fingerprint;

import jakarta.validation.ConstraintViolationException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MissingServletRequestParameterException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.Instant;
import java.util.UUID;

/**
 * Centralized exception handling in line with CERT ERR01-J: full exception
 * details (including stack traces) are logged server-side only, while
 * clients receive a generic message plus a correlation ID for support/logging
 * lookup. This prevents disclosure of internal implementation details
 * (CWE-209) via error responses.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler({ConstraintViolationException.class, MissingServletRequestParameterException.class})
    public ResponseEntity<ErrorResponse> handleValidationException(Exception ex) {
        String errorId = UUID.randomUUID().toString();
        log.warn("Validation error [{}]: {}", errorId, ex.getMessage());

        ErrorResponse body = new ErrorResponse(errorId, "Invalid request parameters.", Instant.now());
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(body);
    }

    @ExceptionHandler(FingerprintException.class)
    public ResponseEntity<ErrorResponse> handleFingerprintException(FingerprintException ex) {
        String errorId = UUID.randomUUID().toString();
        // Full stack trace and cause are logged server-side only.
        log.error("Fingerprint processing error [{}]", errorId, ex);

        ErrorResponse body = new ErrorResponse(
                errorId, "An internal error occurred while processing your request.", Instant.now());
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGenericException(Exception ex) {
        String errorId = UUID.randomUUID().toString();
        log.error("Unhandled error [{}]", errorId, ex);

        ErrorResponse body = new ErrorResponse(errorId, "An unexpected error occurred.", Instant.now());
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }
}
