"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectProperties.java
package com.example.redirect.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.List;

/**
 * Zentrale, außerhalb des Codes pflegbare Konfiguration für den Redirect-Mechanismus.
 * "allowedHosts" bildet die Positivliste (Allow-List) vertrauenswürdiger Ziel-Hosts.
 */
@Component
@ConfigurationProperties(prefix = "app.redirect")
public class RedirectProperties {

    /**
     * Liste der Hostnamen, zu denen absolute Redirects erlaubt sind.
     * Beispiel application.yml:
     * app.redirect.allowed-hosts:
     *   - www.mysite.com
     *   - partner.mysite.com
     */
    private List<String> allowedHosts = new ArrayList<>();

    /**
     * Ziel, zu dem umgeleitet wird, wenn kein oder kein gültiges "url"-Parameter
     * übergeben wurde. MUSS eine interne, vertrauenswürdige Adresse sein.
     */
    private String defaultUrl = "/";

    public List<String> getAllowedHosts() {
        return allowedHosts;
    }

    public void setAllowedHosts(List<String> allowedHosts) {
        this.allowedHosts = allowedHosts;
    }

    public String getDefaultUrl() {
        return defaultUrl;
    }

    public void setDefaultUrl(String defaultUrl) {
        this.defaultUrl = defaultUrl;
    }
}
