package com.example.redirect.service;

import java.util.Optional;

/**
 * Vertrag für die Validierung von potenziellen Redirect-Zielen.
 * Implementierungen MÜSSEN einen Allow-List-Ansatz verfolgen (kein Deny-List-Ansatz),
 * um CWE-601 (Open Redirect) zu verhindern.
 */
public interface RedirectValidationService {

    /**
     * Prüft die übergebene, nicht vertrauenswürdige URL.
     *
     * @param candidateUrl vom Client übergebener Wert des "url"-Parameters
     * @return Optional mit der bereinigten, sicheren Ziel-URL, falls diese
     *         zulässig ist; sonst Optional.empty()
     */
