"}, {"type": "CODE_BLOCK", "language": "java", "content": "// AllowListRedirectValidationService.java
package com.example.redirect.service;

import com.example.redirect.config.RedirectProperties;
import org.springframework.stereotype.Service;
import org.springframework.web.util.UriComponents;
import org.springframework.web.util.UriComponentsBuilder;

import java.util.Locale;
import java.util.Optional;

/**
 * Validiert Redirect-Ziele ausschließlich anhand einer Positivliste (Allow-List)
 * vertrauenswürdiger Hosts. Dieser Ansatz verhindert Open-Redirect- (CWE-601)
 * und SSRF-artige Angriffe (CWE-918), bei denen ein Angreifer beliebige externe
 * oder interne Ziele als Umleitungsziel einschleusen könnte.
 */
@Service
public class AllowListRedirectValidationService implements RedirectValidationService {

    private final RedirectProperties redirectProperties;

    public AllowListRedirectValidationService(RedirectProperties redirectProperties) {
        this.redirectProperties = redirectProperties;
    }

    @Override
    public Optional<String> validate(String candidateUrl) {
        if (candidateUrl == null || candidateUrl.isBlank()) {
            return Optional.empty();
        }

        String trimmed = candidateUrl.trim();

        // Kontrollzeichen (z.B. \r, \n, \t) deuten auf Manipulationsversuche hin
        // und werden generell abgelehnt.
        if (containsControlCharacters(trimmed)) {
            return Optional.empty();
        }

        // Protokoll-relative URLs ("//evil.com") und Backslash-Tricks, mit denen
        // Browser dazu gebracht werden können, den Host zu wechseln, ausschließen.
        if (trimmed.startsWith("//") || trimmed.contains("\\")) {
            return Optional.empty();
        }

        UriComponents uriComponents;
        try {
            uriComponents = UriComponentsBuilder.fromUriString(trimmed).build();
        } catch (IllegalArgumentException ex) {
            return Optional.empty();
        }

        String scheme = uriComponents.getScheme();
        String host = uriComponents.getHost();

        // Fall 1: reiner Pfad ohne Schema/Host -> nur erlaubt, wenn er innerhalb
        // der eigenen Anwendung bleibt (beginnt mit "/", kein Path-Traversal).
        if (scheme == null && host == null) {
            String path = uriComponents.getPath();
            if (path == null || !path.startsWith("/") || path.contains("..")) {
                return Optional.empty();
            }
            return Optional.of(uriComponents.toUriString());
        }

        // Fall 2: absolute URL -> nur http/https und Host aus der Allow-List.
        if (scheme == null
                || (!scheme.equalsIgnoreCase("http") && !scheme.equalsIgnoreCase("https"))) {
            return Optional.empty();
        }
        if (host == null) {
            return Optional.empty();
        }

        String normalizedHost = host.toLowerCase(Locale.ROOT);
        boolean allowed = redirectProperties.getAllowedHosts().stream()
                .anyMatch(allowedHost -> allowedHost.equalsIgnoreCase(normalizedHost));

        if (!allowed) {
            return Optional.empty();
        }

        return Optional.of(uriComponents.toUriString());
    }

    private boolean containsControlCharacters(String value) {
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (Character.isISOControl(c)) {
                return true;
            }
        }
        return false;
    }
}
