"}, {"type": "CODE_BLOCK", "language": "java", "content": "// Slf4jRedirectAuditService.java
package com.example.redirect.service;

import com.example.redirect.dto.RedirectAuditEvent;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

/**
 * Protokolliert Redirect-Ereignisse über einen dedizierten Audit-Logger.
 * Nutzereingaben werden vor dem Schreiben ins Log von CR/LF-Zeichen befreit,
 * um Log-Injection / Log-Forging (CWE-117) zu verhindern.
 */
@Service
public class Slf4jRedirectAuditService implements RedirectAuditService {

    private static final Logger AUDIT_LOG = LoggerFactory.getLogger("REDIRECT_AUDIT");

    @Override
    public void record(RedirectAuditEvent event) {
        if (event.allowed()) {
            AUDIT_LOG.info(
                    "Redirect erlaubt: requestedUrl='{}', targetUrl='{}', clientIp='{}', timestamp='{}'",
                    sanitizeForLog(event.requestedUrl()),
                    sanitizeForLog(event.resolvedTargetUrl()),
                    sanitizeForLog(event.clientIp()),
                    event.timestamp());
        } else {
            AUDIT_LOG.warn(
                    "Redirect abgelehnt: requestedUrl='{}', fallbackUrl='{}', clientIp='{}', timestamp='{}'",
                    sanitizeForLog(event.requestedUrl()),
                    sanitizeForLog(event.resolvedTargetUrl()),
                    sanitizeForLog(event.clientIp()),
                    event.timestamp());
        }
    }

    private String sanitizeForLog(String value) {
        if (value == null) {
            return "";
        }
        return value.replaceAll("[\r\n]", "_");
    }
}
