"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectController.java
package com.example.redirect.controller;

import com.example.redirect.config.RedirectProperties;
import com.example.redirect.dto.RedirectAuditEvent;
import com.example.redirect.service.RedirectAuditService;
import com.example.redirect.service.RedirectValidationService;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.net.URI;
import java.time.Instant;
import java.util.Optional;

/**
 * Stellt den Endpunkt "/go" bereit, über den Nutzer sicher zu einer
 * validierten Ziel-URL weitergeleitet werden.
 *
 * Der Controller selbst enthält keine Validierungslogik (Trennung der
 * Verantwortlichkeiten), sondern delegiert diese vollständig an
 * {@link RedirectValidationService}. Dadurch bleibt die sicherheitsrelevante
 * Logik an einer einzigen, gut testbaren Stelle gebündelt.
 */
@RestController
public class RedirectController {

    private final RedirectValidationService redirectValidationService;
    private final RedirectAuditService redirectAuditService;
    private final RedirectProperties redirectProperties;

    public RedirectController(RedirectValidationService redirectValidationService,
                               RedirectAuditService redirectAuditService,
                               RedirectProperties redirectProperties) {
        this.redirectValidationService = redirectValidationService;
        this.redirectAuditService = redirectAuditService;
        this.redirectProperties = redirectProperties;
    }

    @GetMapping("/go")
    public ResponseEntity<Void> redirect(
            @RequestParam(name = "url", required = false) String url,
            HttpServletRequest request) {

        String clientIp = request.getRemoteAddr();
        String targetUrl;
        boolean allowed;

        if (url == null || url.isBlank()) {
            // Kein Parameter übergeben -> immer zur vertrauenswürdigen Startseite.
            targetUrl = redirectProperties.getDefaultUrl();
            allowed = false;
        } else {
            Optional<String> validated = redirectValidationService.validate(url);
            if (validated.isPresent()) {
                targetUrl = validated.get();
                allowed = true;
            } else {
                // Ungültiges/nicht erlaubtes Ziel -> Fallback statt Weiterleitung
                // zu einer vom Angreifer kontrollierten Adresse.
                targetUrl = redirectProperties.getDefaultUrl();
                allowed = false;
            }
        }

        redirectAuditService.record(new RedirectAuditEvent(
                url,
                targetUrl,
                allowed,
                clientIp,
                Instant.now()
        ));

        return ResponseEntity.status(HttpStatus.FOUND)
                .location(URI.create(targetUrl))
                .build();
    }
}
