/**
 * JAXB-Eingabemodell. Es werden ausschließlich fachliche Datenfelder abgebildet.
 * Es gibt KEINE Felder oder Verarbeitung, die auf XML-ENTITY/DOCTYPE-Konstrukte
 * reagieren - diese werden bereits auf Parser-Ebene (SecureXmlParser) verworfen.
 */
@XmlRootElement(name = "document")
@XmlAccessorType(XmlAccessType.FIELD)
public class XmlDocumentDto {

