Nun der zentrale Baustein gegen XXE: der gehärtete Parser. JAXB selbst bietet keine sicherheitsrelevanten Schalter – laut Cheat Sheet muss man den `Unmarshaller` daher über einen bereits gehärteten `XMLStreamReader` füttern (StAX), bei dem DTDs (`SUPPORT_DTD`) und externe Entities (`IS_SUPPORTING_EXTERNAL_ENTITIES`) explizit deaktiviert sind. Das ist die primäre Verteidigungslinie gegen XXE und gleichzeitig gegen Billion-Laughs-DoS.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureXmlParser.java
package com.example.xmlprocessing.parser;

import com.example.xmlprocessing.dto.XmlDocumentDto;
import com.example.xmlprocessing.exception.XmlProcessingException;
import jakarta.xml.bind.JAXBContext;
import jakarta.xml.bind.JAXBException;
import jakarta.xml.bind.Unmarshaller;
import org.springframework.stereotype.Component;

import javax.xml.stream.XMLInputFactory;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamReader;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;

/**
 * Liest XML-Eingaben ausschließlich über einen gehärteten StAX-Reader ein
 * und übergibt diesen an JAXB. Dadurch werden DOCTYPE-Deklarationen und
 * externe Entities bereits auf Parser-Ebene verworfen (CWE-611 Prävention),
 * unabhängig davon, was der Aufrufer im XML unterzubringen versucht.
 */
@Component
public class SecureXmlParser {

    // Verhindert übermäßig große Eingaben (Denial-of-Service-Schutz, ergänzend zu SUPPORT_DTD=false)
    private static final int MAX_XML_SIZE_BYTES = 100_000;

    private final JAXBContext jaxbContext;

    public SecureXmlParser() {
        try {
            this.jaxbContext = JAXBContext.newInstance(XmlDocumentDto.class);
        } catch (JAXBException e) {
            throw new IllegalStateException("JAXBContext konnte nicht initialisiert werden", e);
        }
    }

    public XmlDocumentDto parse(String xmlData) {
        if (xmlData == null || xmlData.isBlank()) {
            throw new XmlProcessingException("XML-Eingabe darf nicht leer sein");
        }
        if (xmlData.getBytes(StandardCharsets.UTF_8).length > MAX_XML_SIZE_BYTES) {
            throw new XmlProcessingException("XML-Eingabe überschreitet die maximal zulässige Größe");
        }

        XMLInputFactory xmlInputFactory = createHardenedXmlInputFactory();

        XMLStreamReader xmlStreamReader = null;
        try {
            xmlStreamReader = xmlInputFactory.createXMLStreamReader(new StringReader(xmlData));

            Unmarshaller unmarshaller = jaxbContext.createUnmarshaller();
            Object result = unmarshaller.unmarshal(xmlStreamReader);

            if (!(result instanceof XmlDocumentDto)) {
                throw new XmlProcessingException("Unerwarteter Wurzel-Elementtyp im XML-Dokument");
            }
            return (XmlDocumentDto) result;

        } catch (XMLStreamException e) {
            // Wird u.a. ausgelöst, wenn trotz deaktiviertem SUPPORT_DTD ein DOCTYPE vorhanden ist.
            throw new XmlProcessingException("XML konnte nicht sicher gelesen werden");
        } catch (JAXBException e) {
            throw new XmlProcessingException("XML entspricht nicht dem erwarteten Format");
        } finally {
            if (xmlStreamReader != null) {
                try {
                    xmlStreamReader.close();
                } catch (XMLStreamException ignored) {
                    // Ressource wird best-effort geschlossen; kein sicherheitsrelevanter Fehlerfall
                }
            }
        }
    }

    private XMLInputFactory createHardenedXmlInputFactory() {
        XMLInputFactory factory = XMLInputFactory.newInstance();

        try {
            // PRIMÄRER Schutz: DTDs (DOCTYPE) vollständig deaktivieren.
            // Verhindert klassische XXE-Angriffe UND Billion-Laughs-DoS.
            factory.setProperty(XMLInputFactory.SUPPORT_DTD, false);

            // Externe (allgemeine) Entities zusätzlich explizit deaktivieren (Defense in Depth).
            factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, false);

            // Entity-Referenzen nicht automatisch expandieren.
            factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, false);
        } catch (IllegalArgumentException e) {
            // Wenn die zugrunde liegende StAX-Implementierung diese sicherheitskritischen
            // Properties nicht unterstützt, wird bewusst NICHT weiter geparst ("fail closed").
            throw new IllegalStateException(
                    "Der XML-Parser unterstützt die erforderlichen Sicherheitsfeatures nicht", e);
        }

        return factory;
    }
}
", "fileName": "Component_7", "vulnerbility": null}, {"type": "TEXT", "text": "

Damit ist sichergestellt, dass selbst wenn ein Angreifer `<!DOCTYPE foo [<!ENTITY xxe SYSTEM "file:///etc/passwd">]>` einschleust, der Parser mit einer Exception abbricht, **bevor** überhaupt fachliche Daten extrahiert werden.

Als Nächstes die Whitelist-Prüfung für URLs, die als reine Textdaten im XML stehen (z.B. `<externalReference>https://example.com/resource</externalReference>`):

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlWhitelistValidator.java
package com.example.xmlprocessing.validation;

import com.example.xmlprocessing.exception.UrlNotAllowedException;
import org.springframework.stereotype.Component;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;
import java.util.Set;

/**
 * Prüft URLs, die als Fachdaten im XML enthalten sind, gegen eine feste
 * Whitelist von Hosts und Schemas (CWE-601 / SSRF-Prävention, CWE-918).
 *
 * Wichtig: Es wird ein exakter Host-Vergleich durchgeführt (equals),
 * NICHT startsWith/contains - andernfalls wären Bypässe wie
 * "https://example.com.attacker.com" möglich.
 */
@Component
public class UrlWhitelistValidator {

    private static final Set<String> ALLOWED_HOSTS = Set.of(
            "example.com",
            "api.example.com"
    );

    private static final Set<String> ALLOWED_SCHEMES = Set.of("https");

    public void validate(String urlValue) {
        if (urlValue == null || urlValue.isBlank()) {
            throw new UrlNotAllowedException("Leere URL ist nicht zulässig");
        }

        URI uri;
        try {
            uri = new URI(urlValue);
        } catch (URISyntaxException e) {
            throw new UrlNotAllowedException("Ungültiges URL-Format");
        }

        String scheme = uri.getScheme();
        String host = uri.getHost();

        if (scheme == null || !ALLOWED_SCHEMES.contains(scheme.toLowerCase(Locale.ROOT))) {
            throw new UrlNotAllowedException("Nicht erlaubtes URL-Schema");
        }

        if (host == null || !ALLOWED_HOSTS.contains(host.toLowerCase(Locale.ROOT))) {
            throw new UrlNotAllowedException("Host ist nicht in der Whitelist enthalten");
        }
    }
}
", "fileName": "Component_8", "vulnerbility": null}, {"type": "TEXT", "text": "

Erst nach bestandener Whitelist-Prüfung wird die Ressource über einen bewusst restriktiv konfigurierten HTTP-Client geladen – nicht über den XML-Parser:

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ExternalResourceFetcher.java
package com.example.xmlprocessing.client;

import com.example.xmlprocessing.exception.XmlProcessingException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.net.Inet4Address;
import java.net.Inet6Address;
import java.net.InetAddress;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.UnknownHostException;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.Arrays;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Ruft eine zuvor gewhitelistete URL kontrolliert ab. Es werden bewusst
 * Timeouts, ein Antwortgrößenlimit sowie deaktivierte automatische
 * Weiterleitungen verwendet, um SSRF über Redirect-Ketten zu verhindern.
 *
 * Zusätzlich wird die Ziel-URL strikt validiert:
 * - Nur HTTPS erlaubt
 * - Nur explizit erlaubte Hostnamen (Allowlist)
 * - Auflösung der DNS-Namen und Prüfung, dass keine privaten/internen/
 *   loopback/link-local IP-Adressen adressiert werden (Schutz gegen DNS-Rebinding)
 */
@Component
public class ExternalResourceFetcher {

    private static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(3);
    private static final Duration REQUEST_TIMEOUT = Duration.ofSeconds(5);
    private static final int MAX_RESPONSE_BYTES = 50_000;

    private final HttpClient httpClient;
    private final Set<String> allowedHosts;

    public ExternalResourceFetcher(
            @Value("${external-resource.allowed-hosts:}") String allowedHostsConfig) {
        this.httpClient = HttpClient.newBuilder()
                .connectTimeout(CONNECT_TIMEOUT)
                // Redirects werden NICHT automatisch verfolgt, damit ein Angreifer nicht über
                // eine erlaubte URL auf ein nicht gewhitelistetes internes Ziel umleiten kann.
                .followRedirects(HttpClient.Redirect.NEVER)
                .build();

        this.allowedHosts = Arrays.stream(allowedHostsConfig.split(","))
                .map(String::trim)
                .filter(s -> !s.isEmpty())
                .map(s -> s.toLowerCase(Locale.ROOT))
                .collect(Collectors.toUnmodifiableSet());
    }

    public String fetchTextContent(String validatedUrl) {
        URI uri = validateAndParseUrl(validatedUrl);

        try {
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(uri)
                    .timeout(REQUEST_TIMEOUT)
                    .GET()
                    .build();

            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

            if (response.statusCode() != 200) {
                throw new XmlProcessingException("Externe Ressource lieferte einen unerwarteten Statuscode");
            }

            String body = response.body();
            if (body != null && body.getBytes(StandardCharsets.UTF_8).length > MAX_RESPONSE_BYTES) {
                throw new XmlProcessingException("Antwort der externen Ressource überschreitet das zulässige Limit");
            }

            return body;

        } catch (IOException e) {
            throw new XmlProcessingException("Externe Ressource konnte nicht abgerufen werden");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new XmlProcessingException("Abruf der externen Ressource wurde unterbrochen");
        }
    }

    /**
     * Validiert die übergebene URL streng gegen eine Allowlist und stellt sicher,
     * dass sie nicht auf interne/private Netzwerke verweist. Wirft eine
     * XmlProcessingException, falls die URL nicht zulässig ist.
     */
    private URI validateAndParseUrl(String url) {
        if (url == null || url.isBlank()) {
            throw new XmlProcessingException("Externe Ressourcen-URL darf nicht leer sein");
        }

        URI uri;
        try {
            uri = new URI(url);
        } catch (URISyntaxException e) {
            throw new XmlProcessingException("Externe Ressourcen-URL ist ungültig");
        }

        if (uri.getScheme() == null || !"https".equalsIgnoreCase(uri.getScheme())) {
            throw new XmlProcessingException("Nur HTTPS-URLs sind für externe Ressourcen zulässig");
        }

        String host = uri.getHost();
        if (host == null || host.isBlank()) {
            throw new XmlProcessingException("Externe Ressourcen-URL enthält keinen gültigen Host");
        }

        String normalizedHost = host.toLowerCase(Locale.ROOT);

        if (allowedHosts.isEmpty() || !allowedHosts.contains(normalizedHost)) {
            throw new XmlProcessingException("Der Host der externen Ressource ist nicht in der Allowlist enthalten");
        }

        // Benutzerinformationen (z.B. user:pass@host) sind nicht erlaubt, da sie
        // zur Verschleierung des tatsächlichen Ziels genutzt werden könnten.
        if (uri.getRawUserInfo() != null) {
            throw new XmlProcessingException("Externe Ressourcen-URL darf keine Zugangsdaten enthalten");
        }

        // Schutz gegen DNS-Rebinding: Auflösung des Hosts und Prüfung auf
        // private/interne/loopback/link-local Adressen.
        try {
            InetAddress[] addresses = InetAddress.getAllByName(normalizedHost);
            for (InetAddress address : addresses) {
                if (isDisallowedAddress(address)) {
                    throw new XmlProcessingException(
                            "Externe Ressource löst auf eine nicht erlaubte interne Adresse auf");
                }
            }
        } catch (UnknownHostException e) {
            throw new XmlProcessingException("Host der externen Ressource konnte nicht aufgelöst werden");
        }

        return uri;
    }

    private boolean isDisallowedAddress(InetAddress address) {
        if (address.isLoopbackAddress()
                || address.isAnyLocalAddress()
                || address.isLinkLocalAddress()
                || address.isMulticastAddress()
                || address.isSiteLocalAddress()) {
            return true;
        }

        if (address instanceof Inet4Address) {
            byte[] bytes = address.getAddress();
            int firstOctet = bytes[0] & 0xFF;
            int secondOctet = bytes[1] & 0xFF;

            // 0.0.0.0/8
            if (firstOctet == 0) {
                return true;
            }
            // 100.64.0.0/10 (Carrier-grade NAT)
            if (firstOctet == 100 && (secondOctet >= 64 && secondOctet <= 127)) {
                return true;
            }
            // 169.254.0.0/16 (link-local, redundant, aber explizit)
            if (firstOctet == 169 && secondOctet == 254) {
                return true;
            }
            // 192.0.0.0/24, 192.0.2.0/24 (Dokumentation)
            if (firstOctet == 192 && (secondOctet == 0 || secondOctet == 2)) {
                return true;
            }
            // 198.18.0.0/15, 198.51.100.0/24 (Benchmark/Dokumentation)
            if (firstOctet == 198 && (secondOctet == 18 || secondOctet == 19 || secondOctet == 51)) {
                return true;
            }
            // 203.0.113.0/24 (Dokumentation)
            if (firstOctet == 203 && secondOctet == 0) {
                return true;
            }
            // 240.0.0.0/4 (reserviert) und 255.255.255.255 (broadcast)
            if (firstOctet >= 240) {
                return true;
            }
        }

        if (address instanceof Inet6Address) {
            Inet6Address inet6 = (Inet6Address) address;
            byte[] bytes = inet6.getAddress();

            // Unique local addresses fc00::/7
            if ((bytes[0] & 0xFE) == 0xFC) {
                return true;
            }
            // IPv4-mapped Adressen ebenfalls gegen die IPv4-Regeln prüfen
            if (inet6.isIPv4CompatibleAddress()) {
                try {
                    InetAddress mapped = InetAddress.getByAddress(
                            new byte[] {bytes[12], bytes[13], bytes[14], bytes[15]});
                    if (isDisallowedAddress(mapped)) {
                        return true;
                    }
                } catch (UnknownHostException e) {
                    return true;
                }
            }
        }

        return false;
    }
}
