Der Service orchestriert die drei Schritte in der richtigen Reihenfolge – **erst** sicheres Parsen, **dann** Whitelist-Prüfung, **dann** kontrollierter Abruf:

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// XmlService.java
package com.example.xmlprocessing.service;

import com.example.xmlprocessing.client.ExternalResourceFetcher;
import com.example.xmlprocessing.dto.ResolvedExternalReference;
import com.example.xmlprocessing.dto.XmlDocumentDto;
import com.example.xmlprocessing.dto.XmlProcessingResponse;
import com.example.xmlprocessing.parser.SecureXmlParser;
import com.example.xmlprocessing.validation.UrlWhitelistValidator;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;

@Service
public class XmlService {

    private final SecureXmlParser secureXmlParser;
    private final UrlWhitelistValidator urlWhitelistValidator;
    private final ExternalResourceFetcher externalResourceFetcher;

    public XmlService(SecureXmlParser secureXmlParser,
                       UrlWhitelistValidator urlWhitelistValidator,
                       ExternalResourceFetcher externalResourceFetcher) {
        this.secureXmlParser = secureXmlParser;
        this.urlWhitelistValidator = urlWhitelistValidator;
        this.externalResourceFetcher = externalResourceFetcher;
    }

    public XmlProcessingResponse processXml(String xmlData) {
        // 1. Sicheres Parsen: DTDs/externe Entities sind im Parser deaktiviert (CWE-611-Schutz).
        XmlDocumentDto document = secureXmlParser.parse(xmlData);

        // 2. Jede im XML als Fachdatum enthaltene URL wird gegen eine Whitelist geprüft
        //    und erst danach über einen kontrollierten HTTP-Client abgerufen (CWE-601/CWE-918-Schutz).
        //    Es findet zu keinem Zeitpunkt eine Auflösung über den XML-Parser selbst statt.
        List<ResolvedExternalReference> resolvedReferences = new ArrayList<>();
        for (String url : document.getExternalReferences()) {
            urlWhitelistValidator.validate(url);
            String content = externalResourceFetcher.fetchTextContent(url);
            resolvedReferences.add(new ResolvedExternalReference(url, content));
        }

        XmlProcessingResponse response = new XmlProcessingResponse();
        response.setTitle(document.getTitle());
        response.setDescription(document.getDescription());
        response.setResolvedReferences(resolvedReferences);
        return response;
    }
}
