Der Controller ist bewusst schlank: Er nimmt nur `application/xml` an und liefert nur `application/json`. Die eigentliche JSON-Serialisierung übernimmt Springs Standard-Jackson-`HttpMessageConverter` automatisch, sobald ein Java-Objekt zurückgegeben wird:

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// XmlController.java
package com.example.xmlprocessing.controller;

import com.example.xmlprocessing.dto.XmlProcessingResponse;
import com.example.xmlprocessing.service.XmlService;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/xml")
public class XmlController {

    private final XmlService xmlService;

    public XmlController(XmlService xmlService) {
        this.xmlService = xmlService;
    }

    @PostMapping(consumes = MediaType.APPLICATION_XML_VALUE, produces = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<XmlProcessingResponse> processXml(@RequestBody String xmlData) {
        XmlProcessingResponse response = xmlService.processXml(xmlData);
        return ResponseEntity.ok(response);
    }
}
