Fehler werden zentral und **informationsarm** behandelt, um Stacktraces oder interne Details nicht an den Client zu leaken (CWE-209):

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.xmlprocessing.controller;

import com.example.xmlprocessing.dto.ErrorResponse;
import com.example.xmlprocessing.exception.UrlNotAllowedException;
import com.example.xmlprocessing.exception.XmlProcessingException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(UrlNotAllowedException.class)
    public ResponseEntity<ErrorResponse> handleUrlNotAllowed(UrlNotAllowedException e) {
        log.warn("Zugriff auf nicht gewhitelistete URL verweigert: {}", e.getMessage());
        return ResponseEntity.status(HttpStatus.FORBIDDEN)
                .body(new ErrorResponse("Zugriff auf die angeforderte externe Ressource ist nicht erlaubt"));
    }

    @ExceptionHandler(XmlProcessingException.class)
    public ResponseEntity<ErrorResponse> handleXmlProcessing(XmlProcessingException e) {
        log.warn("XML-Verarbeitung fehlgeschlagen: {}", e.getMessage());
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorResponse("Die XML-Eingabe konnte nicht verarbeitet werden"));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGeneric(Exception e) {
        log.error("Unerwarteter Fehler bei der XML-Verarbeitung", e);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(new ErrorResponse("Ein interner Fehler ist aufgetreten"));
    }
}
