### 4. Globaler Exception Handler

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.customerxxe.exception;

import com.example.customerxxe.dto.ErrorResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.Instant;

/**
 * Zentrale Fehlerbehandlung. Stellt sicher, dass niemals interne Details
 * (Stacktraces, Dateipfade, Parser-Meldungen) an den Client gelangen (CWE-209).
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(InvalidCustomerNameException.class)
    public ResponseEntity<ErrorResponse> handleInvalidCustomerName(InvalidCustomerNameException ex) {
        return buildResponse(HttpStatus.BAD_REQUEST, ex.getMessage());
    }

    @ExceptionHandler(CustomerNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleCustomerNotFound(CustomerNotFoundException ex) {
        return buildResponse(HttpStatus.NOT_FOUND, ex.getMessage());
    }

    @ExceptionHandler(XmlProcessingException.class)
    public ResponseEntity<ErrorResponse> handleXmlProcessing(XmlProcessingException ex) {
        // Vollständige technische Ursache nur serverseitig loggen.
        log.error("Sichere XML-Verarbeitung fehlgeschlagen", ex);
        return buildResponse(HttpStatus.INTERNAL_SERVER_ERROR, "Die Kundendaten konnten nicht verarbeitet werden.");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleUnexpected(Exception ex) {
        log.error("Unerwarteter Fehler", ex);
        return buildResponse(HttpStatus.INTERNAL_SERVER_ERROR, "Es ist ein unerwarteter Fehler aufgetreten.");
    }

    private ResponseEntity<ErrorResponse> buildResponse(HttpStatus status, String message) {
        ErrorResponse body = new ErrorResponse(Instant.now(), status.value(), status.getReasonPhrase(), message);
        return ResponseEntity.status(status).body(body);
    }
}
