### 6. Strikter ErrorHandler für die Schema-Validierung

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// StrictErrorHandler.java
package com.example.customerxxe.xml;

import org.xml.sax.ErrorHandler;
import org.xml.sax.SAXException;
import org.xml.sax.SAXParseException;

/**
 * Sorgt dafür, dass JEDE Verletzung der XSD-Validierung (warning, error, fatalError)
 * den Parse-Vorgang abbricht, statt sie stillschweigend zu ignorieren.
 * Ohne diesen Handler würde der Standard-DocumentBuilder Validierungsfehler
 * unter Umständen nur protokollieren, aber trotzdem ein Dokument liefern.
 */
public class StrictErrorHandler implements ErrorHandler {

    @Override
    public void warning(SAXParseException exception) throws SAXException {
        throw exception;
    }

    @Override
    public void error(SAXParseException exception) throws SAXException {
        throw exception;
    }

    @Override
    public void fatalError(SAXParseException exception) throws SAXException {
        throw exception;
    }
}
