### 7. Zentrale, gehärtete Parser-Factory (Kern der XXE-Prävention)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureXmlParserFactory.java
package com.example.customerxxe.xml;

import com.example.customerxxe.exception.XmlProcessingException;
import org.springframework.stereotype.Component;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import java.io.IOException;
import java.io.InputStream;
import java.io.StringReader;

/**
 * Zentrale Stelle, an der XML sicher geparst wird.
 *
 * Umgesetzte Maßnahmen gegen XXE (CWE-611):
 *  - disallow-doctype-decl = true         -> DOCTYPE komplett verboten (primäre Verteidigung,
 *                                             schützt auch vor "Billion Laughs")
 *  - external-general-entities = false    -> keine externen Entities
 *  - external-parameter-entities = false  -> keine externen Parameter-Entities
 *  - load-external-dtd = false            -> keine externen DTDs nachladen
 *  - XIncludeAware = false                -> kein XInclude
 *  - expandEntityReferences = false       -> keine Entity-Expansion
 *  - FEATURE_SECURE_PROCESSING = true     -> zusätzliche JAXP-Schutzmechanismen
 *  - No-Op EntityResolver                 -> zusätzliche Absicherung, falls doch
 *                                             eine Entity referenziert wird
 *  - Strikte XSD-Validierung              -> nur strukturell erwartete Dokumente werden akzeptiert
 *  - ACCESS_EXTERNAL_DTD/SCHEMA = ""       -> auch die Schema-Validierung selbst lädt nichts
 *                                             von außen nach (verhindert SSRF via XSD)
 */
@Component
public class SecureXmlParserFactory {

    public Document parseAndValidate(InputStream xmlInputStream, InputStream xsdInputStream) {
        try {
            Schema schema = buildSchema(xsdInputStream);

            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
            dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            dbf.setXIncludeAware(false);
            dbf.setExpandEntityReferences(false);
            dbf.setNamespaceAware(true);
            dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            dbf.setSchema(schema);

            DocumentBuilder builder = dbf.newDocumentBuilder();
            builder.setEntityResolver((publicId, systemId) -> new InputSource(new StringReader("")));
            builder.setErrorHandler(new StrictErrorHandler());

            return builder.parse(xmlInputStream);

        } catch (ParserConfigurationException | SAXException | IOException e) {
            throw new XmlProcessingException(
                    "Die Kunden-XML-Datenquelle konnte nicht sicher geparst/validiert werden.", e);
        }
    }

    private Schema buildSchema(InputStream xsdInputStream) throws SAXException {
        SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
        // Auch die Schema-Verarbeitung darf keine externen Ressourcen nachladen.
        schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
        return schemaFactory.newSchema(new StreamSource(xsdInputStream));
    }
}
