### 8. Eingabevalidierung (Schutz vor Injection und Missbrauch)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerNameValidator.java
package com.example.customerxxe.validation;

import com.example.customerxxe.exception.InvalidCustomerNameException;
import org.springframework.stereotype.Component;

import java.util.regex.Pattern;

/**
 * Strikte Allow-List-Validierung des customerName-Parameters.
 * Auch wenn die XPath-Suche parametrisiert erfolgt (siehe CustomerXmlRepository),
 * ist eine zusätzliche Eingabevalidierung Best Practice (Defense in Depth,
 * OWASP A03:2021 Injection) und begrenzt zugleich die Länge gegen Resource-Abuse.
 */
@Component
public class CustomerNameValidator {

    private static final Pattern ALLOWED_NAME_PATTERN = Pattern.compile("^[\\p{L} .'-]{1,100}$");

    public void validate(String customerName) {
        if (customerName == null || customerName.isBlank()) {
            throw new InvalidCustomerNameException("Der Parameter customerName darf nicht leer sein.");
        }
        if (!ALLOWED_NAME_PATTERN.matcher(customerName).matches()) {
            throw new InvalidCustomerNameException(
                    "Der Parameter customerName enthält nicht erlaubte Zeichen.");
        }
    }
}
