### 9. Repository mit parametrisierter XPath-Suche (Schutz vor XPath-Injection)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerXmlRepository.java
package com.example.customerxxe.repository;

import com.example.customerxxe.config.CustomerXmlProperties;
import com.example.customerxxe.dto.CustomerDto;
import com.example.customerxxe.exception.XmlProcessingException;
import com.example.customerxxe.xml.SecureXmlParserFactory;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Repository;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

import javax.xml.XMLConstants;
import javax.xml.namespace.QName;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathExpressionException;
import javax.xml.xpath.XPathFactory;
import java.io.IOException;
import java.io.InputStream;
import java.util.Optional;

/**
 * Liest die Kunden-XML-Datei über die gehärtete SecureXmlParserFactory ein
 * und sucht den Kunden anhand einer XPath-Abfrage.
 *
 * Wichtig: Der vom Client stammende customerName wird NICHT in den
 * XPath-Ausdruck hineinkonkateniert, sondern als gebundene Variable
 * über einen XPathVariableResolver übergeben. Damit ist XPath-Injection
 * (CWE-643) strukturell ausgeschlossen.
 */
@Repository
public class CustomerXmlRepository {

    private static final QName SEARCH_NAME_VARIABLE = new QName("searchName");

    private final CustomerXmlProperties properties;
    private final SecureXmlParserFactory parserFactory;

    public CustomerXmlRepository(CustomerXmlProperties properties, SecureXmlParserFactory parserFactory) {
        this.properties = properties;
        this.parserFactory = parserFactory;
    }

    public Optional<CustomerDto> findByName(String customerName) {
        Document document = loadDocument();

        try {
            XPathFactory xPathFactory = XPathFactory.newInstance();
            xPathFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            xPathFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

            XPath xPath = xPathFactory.newXPath();
            xPath.setXPathVariableResolver(variableName ->
                    SEARCH_NAME_VARIABLE.equals(variableName) ? customerName : null);

            // Konstanter Ausdruck; der Suchwert wird ausschließlich über die Variable gebunden.
            XPathExpression expression = xPath.compile("/customers/customer[name = $searchName]");
            NodeList nodes = (NodeList) expression.evaluate(document, XPathConstants.NODESET);

            if (nodes.getLength() == 0) {
                return Optional.empty();
            }

            return Optional.of(mapToDto((Element) nodes.item(0)));

        } catch (XPathExpressionException e) {
            throw new XmlProcessingException("Die Kundensuche konnte nicht ausgeführt werden.", e);
        }
    }

    private Document loadDocument() {
        try (InputStream xmlStream = new ClassPathResource(properties.getDataFile()).getInputStream();
             InputStream xsdStream = new ClassPathResource(properties.getSchemaFile()).getInputStream()) {
            return parserFactory.parseAndValidate(xmlStream, xsdStream);
        } catch (IOException e) {
            throw new XmlProcessingException("Die Kunden-XML-Datenquelle konnte nicht geladen werden.", e);
        }
    }

    private CustomerDto mapToDto(Element customerElement) {
        return new CustomerDto(
                customerElement.getAttribute("id"),
                getChildText(customerElement, "name"),
                getChildText(customerElement, "email"),
                getChildText(customerElement, "city")
        );
    }

    private String getChildText(Element parent, String tagName) {
        NodeList children = parent.getElementsByTagName(tagName);
        if (children.getLength() == 0) {
            return "";
        }
        return children.item(0).getTextContent();
    }
}
