package com.example.customerxxe.service;

import com.example.customerxxe.dto.CustomerDto;
import com.example.customerxxe.exception.CustomerNotFoundException;
import com.example.customerxxe.repository.CustomerXmlRepository;
import com.example.customerxxe.validation.CustomerNameValidator;
import org.springframework.stereotype.Service;

@Service
public class CustomerServiceImpl implements CustomerService {

    private final CustomerNameValidator validator;
    private final CustomerXmlRepository repository;

    public CustomerServiceImpl(CustomerNameValidator validator, CustomerXmlRepository repository) {
        this.validator = validator;
        this.repository = repository;
    }

    @Override
    public CustomerDto findByName(String customerName) {
        validator.validate(customerName);

        return repository.findByName(customerName)
                .orElseThrow(() -> new CustomerNotFoundException("Es wurde kein Kunde mit diesem Namen gefunden."));
    }
}
