package com.example.customerxxe.controller;

import com.example.customerxxe.dto.CustomerDto;
import com.example.customerxxe.service.CustomerService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * GET /api/customers/search?customerName=John+Doe
 *
 * Der Controller enthält bewusst keinerlei Parsing- oder Validierungslogik -
 * er delegiert vollständig an den Service, der Validierung, sicheres Parsen
 * und Suche orchestriert.
 */
@RestController
public class CustomerXmlSearchController {

    private final CustomerService customerService;

    public CustomerXmlSearchController(CustomerService customerService) {
        this.customerService = customerService;
    }

    @GetMapping("/api/customers/search")
    public ResponseEntity<CustomerDto> searchCustomer(@RequestParam("customerName") String customerName) {
        CustomerDto customer = customerService.findByName(customerName);
        return ResponseEntity.ok(customer);
    }
}
