## Testressourcen für den lokalen Testlauf

Diese Dateien gehören unter `src/main/resources/` und sind keine Java-Klassen, sondern die Datengrundlage für den Test.

**XSD-Schema** – erzwingt eine strikte Struktur und verhindert, dass "kreative" oder manipulierte Dokumente akzeptiert werden:

"}, {"type": "CODE_BLOCK", "language": "xml", "content": "<!-- customers.xsd -->
<?xml version="1.0" encoding="UTF-8"?>
<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema"
           elementFormDefault="qualified">

    <xs:element name="customers">
        <xs:complexType>
            <xs:sequence>
                <xs:element name="customer" minOccurs="0" maxOccurs="unbounded">
                    <xs:complexType>
                        <xs:sequence>
                            <xs:element name="name" type="xs:string"/>
                            <xs:element name="email" type="xs:string"/>
                            <xs:element name="city" type="xs:string"/>
                        </xs:sequence>
                        <xs:attribute name="id" type="xs:string" use="required"/>
                    </xs:complexType>
                </xs:element>
            </xs:sequence>
        </xs:complexType>
    </xs:element>
</xs:schema>
", "fileName": "Component_15", "vulnerbility": null}, {"type": "TEXT", "text": "

